            if (res(i)(i) < 0) {
                flag = false
            }
        }
        if (!flag) {
            println("NEGATIVE CYCLE")
        } else {
            for (r <- res) {
                for (i <- 0 until r.size) {
                    if (i > 0) print(" ")
                    if (r(i) == Int.MaxValue) print("INF")
