#define FOR(a,b) for(int a=0;a<b;a++)
using namespace std;
using ll=long long;
static const int MAX = 100;
static const ll INF = (1LL << 32);
int n;
ll d[MAX][MAX];

void floyd() {
	FOR(k, n) {
		FOR(i, n) {
			if (d[i][k] == INF) continue;
			FOR(j, n) {
				if (d[k][j] == INF) continue;
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}

int main() {
	int e, s, t, w;
	cin >> n >> e;
	FOR(i, n) {
		FOR(j, n) {
			d[i][j] = (i == j) ? 0 : INF;
		}
	}
	FOR(i, e) {
		cin >> s >> t >> w;
		d[s][t] = w;
	}
	floyd();
	bool neg;
	FOR(i, n) {
		if (d[i][i] < 0) {
			neg = 1;
			cout << "NEGATIVE CYCLE" << endl;
			return 0;
		}
	}
	FOR(i, n) {
		FOR(j, n) {
			if (j > 0) cout << ' ';
			if (d[i][j] == INF) cout << "INF";
			else cout << d[i][j];
		}
		cout << endl;
	}
}

#include <bits/stdc++.h>

using namespace std;

int const MAX_E = 100;
int const INF = INT_MAX;

int edge[MAX_E][MAX_E];

int main() {

  int V, E;  cin >> V >> E;

  fill(edge[0], edge[MAX_E], INF);

  for(int i=0; i<V; i++) edge[i][i] = 0;

  for(int i=0; i<E; i++) {
    int s, t, d; cin >> s >> t >> d;
    edge[s][t] = d;
  }

  for(int k=0; k<V; k++) {
    for(int i=0; i<V; i++) {
      for(int j=0; j<V; j++) {
	if(edge[i][k] != INF && edge[k][j] != INF) {
	  edge[i][j] = min(edge[i][j], edge[i][k] + edge[k][j]);
	}
      }
    }
  }

  for(int i=0; i<V; i++) {
    if(edge[i][i] < 0) {
      cout << "NEGATIVE CYCLE" << endl;
      exit(0);
    }
  }

  for(int i=0; i<V; i++) {
    for(int j=0; j<V; j++) {
      if(j) cout << " ";
      if(edge[i][j] == INF) cout << "INF";
      else cout << edge[i][j];
    }
    cout << endl;
  }

  return 0;
}

