const ll INF = 1LL<<32;
int n,m;
ll dp[110][110];
void floyd(){
    for(int k = 0 ; k<n ; k++){
        for(int i = 0 ; i<n ; i++){
            if(dp[i][k] == INF)
                continue;
            for(int j = 0 ; j<n ; j++){
                if(dp[k][j] == INF)
                    continue;
                dp[i][j] = min(dp[i][j] , dp[i][k]+dp[k][j]);
            }
        }
    }
}
int main(){
    cin>>n>>m;
    for(int i = 0 ; i<n ; i++){
        for(int j = 0 ; j<n ; j++){
            if(i == j)
                dp[i][j] = 0;
            else
                dp[i][j] = INF;
        }
    }

    for(int i = 0 ; i<m ; i++){
        int s,t,d;
        cin>>s>>t>>d;
        dp[s][t] = d;
    }
