            int v = g[j][k].to;
            T c = g[j][k].val;
            if( d[v] > d[u] + c){
              d[v] = d[u] + c;
              p[v] = u;
            }
          }
        }
      }
      rep(i, g.size()){
        if(d[i] == INF)continue;
        rep(j, g[i].size()){
          int u = i;
          int v = g[i][j].to;
          T c = g[i][j].val;
          if( d[v] > d[u] + c){
            return false;
          }
        }
      }
      return true;
    }

    bool warshall_floyd(){
      tmp.resize(n, vector<T>(n,INF));

      rep(i,n)tmp[i][i] = 0;
      rep(i,n)rep(j, g[i].size()){
        tmp[i][g[i][j].to] = g[i][j].val;
      }
