struct WarshallFloyd{
    int n;
    vector<vll> d;

    WarshallFloyd(int n) : n(n), d(n, vll(n, INF)) {
        REP(i, n) d[i][i] = 0;
    }

    void add_edge(int s, int t, ll c) {
        d[s][t] = c;
    }

    ll query(int s, int t) {
        return d[s][t];
    }

    WarshallFloyd& operator()() {
        REP(k, n) {
            REP(i, n) REP(j, n) {
                if (d[i][k] == INF || d[k][j] == INF) continue;
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
            }
        }

        return *this;
    }
};

