//
// 全頂点対間最短路を求める、Floyd-Warshall のアルゴリズム
//
// cf.
//
//
// verified:
//   AOJ Course GRL_1_C Shortest Path - All Pairs Shortest Path
//     http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_1_C&lang=jp
//


/*
    dp[a][b] := a から　b への距離

 として初期化しておいて、アルゴリズム終了後には

    dp[a][b] := a から　b への最短距離

 が格納される。注意点として、初期化時に dp[a][a] = 0 となるようにする必要がある。
 なお負閉路判定に用いることもできて、

 - 負閉路がなければ、任意の頂点 a に対して dp[a][a] = 0
 - 負閉路があったら、ある頂点 a に対して dp[a][a] < 0

 */


#include <iostream>
#include <vector>
using namespace std;
const int INF = 1000000007;

int main() {
    int V, E; cin >> V >> E;

    // initialization of Floyd-Warshall
    vector<vector<int> > dp(V, vector<int>(V, INF));
    for (int i = 0; i < V; ++i) dp[i][i] = 0;  // necessary

    // input
    for (int e = 0; e < E; ++e) {
        int a, b, w; cin >> a >> b >> w;
        dp[a][b] = w;
    }

    // Floyd-Warshall
    for (int k = 0; k < V; ++k)
        for (int i = 0; i < V; ++i)
            for (int j = 0; j < V; ++j)
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);

    // output
    bool isnegative = false;
    for (int v = 0; v < V; ++v) if (dp[v][v] < 0) isnegative = true;
    if (isnegative) puts("NEGATIVE CYCLE");
    else {
        for (int i = 0; i < V; ++i) {
            for (int j = 0; j < V; ++j) {
                if (dp[i][j] < INF) cout << dp[i][j];
                else cout << "INF";
                if (j != V-1) cout << " ";
            }
            cout << endl;
        }
    }
}

#include <bits/stdc++.h>
#define REP(i,n) for (int i = 0; i <(n); ++i)
#define ALL(v) v.begin(), v.end()
using namespace std;

static const int MAX = 100;
static const long long INFTY = (1LL<<32);


//===================================
// Washall floyd: ワ−シャル・フロイド
// 全点対間の最短経路問題に利用
// O[|v|^3]
// v：頂点数
//===================================


int n;
long long d[MAX][MAX];  //d[i][j]の最短コストを記録するDPテーブル

void floyd() {

  for( int k = 0; k < n; k++){         //経由する頂点数
    for(int i = 0; i < n; i++){         //始点
      if( d[i][k] == INFTY ) continue;

      for(int j = 0; j < n; j++){       //終点
      if( d[k][j] == INFTY ) continue;
      d[i][j] = min(d[i][j], d[i][k] + d[k][j]);

      }
    }
  }
}


int main() {
  int e, u, v, c; //e: 辺の数, 頂点 u --> 頂点 v のコスト ｃ
  cin >> n >> e;

  //隣接行列リストの初期化 始点 --> 始点 を 0 に，　それ以外を　INFTY
  for( int i = 0; i < n; i++){
    for( int j = 0; j < n; j++){
      if(i == j) d[i][j] = 0;
      else d[i][j] = INFTY;
      //d[i][j] = ((i == j) ? 0 : INFTY);
    }
  }

  //隣接行列リストとして入力
  for(int i = 0; i < e; i++){
    cin >> u >> v >> c;
