    }

    vector<vector<int> > d(V,vector<int>(V,INF)), p(V,vector<int>(V,-2));
    bool neg_cycle = johnson(G,d,p);

    if(neg_cycle) cout << "NEGATIVE CYCLE" << endl;
    else rep(i,V) {
            rep(j,V) {
                if (d[i][j] == INF) cout << "INF";
                else cout << d[i][j];
                if(j != V-1) cout << " ";
            }
