#include<bits/stdc++.h>
using namespace std;
#define ll long long

ll d[100+10],w[9900+100],to[9900+100],from[9900+100];
const ll inf=pow(2,60);

bool relax(int e){
	if(d[to[e]]>d[from[e]]+w[e] && d[from[e]]!=inf){
		d[to[e]]=d[from[e]]+w[e];
		return true;
	}
	return false;
}

int main(){
	int n,m;
	cin>>n>>m;
	for(int i=0;i<m;i++){
		int t,k,q;
		cin>>t>>k>>q;
		w[i]=q;
		from[i]=t;
		to[i]=k;
	}
	for(int i=0;i<n;i++){
		fill(d,d+n,inf);
		d[i]=0;
		for(int i=0;i<n-1;i++){
			for(int e=0;e<m;e++)
				relax(e);
		}
		for(int e=0;e<m;e++){
			if(relax(e)){
				cout<<"NEGATIVE CYCLE";
				return 0;
			}
		}
		for(int i=0;i<n;i++){
			if(d[i]==inf)
				cout<<"INF";
			else
				cout<<d[i];
			if(i!=m-1)
				cout<<' ';
		}
		cout<<endl;
	}
}

