#define INF 0x3f3f3f3f
using namespace std;
typedef long long LL;
const int MAXN = 1e5+10;

int a[105][105];

void floyd(int v)
{
	for(int k = 0; k < v; ++k)
	{
		for(int i = 0; i < v; ++i)
		{
			for(int j = 0; j < v; ++j)
			{
				a[i][j] = min(a[i][j], a[i][k]+a[k][j]);
			}
		}
	}
}

int main(void)
{
	ios::sync_with_stdio(false); 
	//cin.tie(0);
	int v,e,x,y,d;
	bool neg = false;
	memset(a,INF,sizeof a);
	cin>>v>>e;
	for(int i = 0; i < v; ++i)
		a[i][i] = 0;
	for(int i  = 0; i < e; ++i)
	{
		cin>>x>>y>>d;
		a[x][y] = d;
	}
	floyd(v);

	for(int i = 0; i < v; ++i)
		if(a[i][i] < 0)	neg = true;
	if(neg)
	{
		cout<<"NEGATIVE CYCLE\n";
		return 0;
	} 
	for(int i = 0; i < v; ++i)
	{
		for(int j = 0; j < v; ++j)
		{
			if(j)	cout<<' ';
			if(a[i][j] < INF)
				cout<<a[i][j];
			else
				cout<<"INF";
		}
		cout<<'\n';
	}
	return 0;
}

