bool bellmanford(int start, vector<int>& d)
{
    d.resize(V);
    fill(begin(d), end(d), INF);
    d[start] = 0;

    REP(i, V) {
        REP(from, V) {
            if(d[from] == INF) continue;
            for(Edge e : G[from]) {
                int d_new = d[from] + e.cost;
                if(d_new < d[e.to]) {
                    d[e.to] = d_new;
                    if(i == V-1) return false;
                }
            }
        }
    }

    return true;
}

void solve()
{
    vector<vector<int>> D(V);
    for(auto& d : D) {
        d.resize(V);
    }

    bool allok = true;
    REP(start, V) {
        auto& d = D[start];
        if(!bellmanford(start, d)) {
            allok = false;
            break;
        }
    }

    if(!allok) {
        cout << "NEGATIVE CYCLE" << "\n";
    }
    else {
        REP(start, V) {
            auto& d = D[start];
            REP(v, V) {
                if(d[v] == INF) {
                    cout << "INF";
                }
                else {
                    cout << d[v];
                }
                cout << (v == V-1 ? "\n" : " ");
            }
        }
    }
}

