void e2m(Matrix &g,Edges edges,bool directed,length infinity=linf){
	each(g)e.resize(g.size(),infinity);
	rep(g.size())g[i][i]=0;
	each(edges){
		chmin(g[e.src][e.to],e.cost);
		if(!directed)chmin(g[e.to][e.src],e.cost);
	}
}

