void floyd()
{
  for(int k=0; k<n; k++)
    for(int i=0; i<n; i++)
    {
      if(adj[i][k] == INFTY) continue;
      for(int j=0; j<n; j++)
      {
        if(adj[k][j] == INFTY) continue;
        adj[i][j] = min(adj[i][j], adj[i][k] + adj[k][j]);
      }
    }
}

