template<typename T>
void WarshallFloyd(vector<vector<T>> &G, T inf) {

    int N = G.size();
    for (int k = 0; k < N; ++k) {
        for (int i = 0; i < N; ++i) {
            if (G[i][k] == inf) continue;
            for (int j = 0; j < N; ++j) {
                if (G[k][j] == inf) continue;
                G[i][j] = min(G[i][j],G[i][k]+G[k][j]);
            }
        }
    }
}

