        }
    }

    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            if (G[i][j] < (1LL << 40)) cout << G[i][j];
            else cout << "INF";
            if (j < V - 1) cout << " ";
            else cout << endl;
        }
    }

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;
#define MAX_V 100
#define MAX_E 9900
#define INF 1e9

int V, E;
int d[MAX_V][MAX_V];

void init(){
  for(int i = 0; i < V; i++){
    for(int j = 0; j < V; j++){
      if(i == j) d[i][j] = 0;
      else d[i][j] = INF;
    }
  }
}

void warshall_floyd(){
  for(int k = 0; k < V; k++){
    for(int i = 0; i < V; i++){
      for(int j = 0; j < V; j++) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
    }
  }
}

bool hasNegativeCycle(){
  for(int i = 0; i < V; i++){
    if(d[i][i] < 0) return true;
  }
  return false;
}

int main(void){
