class Edge{
public:
	Edge(bool b = false):exist(b),distance(0){};
	Edge(int d):exist(true),distance(d){};
	Edge(const Edge &other){};
	bool is_exist() const {return exist;}
	int get() const {if (exist){return distance;}else{throw;}}
	Edge &operator=(const int &d){distance = d;exist = true;return (*this);}
	Edge &operator=(const Edge &other){
		if (other.is_exist()){
			return (*this)=other.distance;
		}else{
			return (*this);
		}
	}
	Edge operator+(const Edge &other){
		if (exist and other.is_exist()){
			return (Edge(distance + other.distance));
		}else{
			return (Edge(false));
		}
	}
	const bool operator>(const Edge &other){
		if (other.exist){
			if (exist){
				return distance > other.distance;
			}else{
				return true;
			}
		}else{
			return false;
		}
	}
	const bool operator<(const int &d){return (distance < d);}
private:
	bool exist;
	int distance;
};/*
