int spfa(int start)
{
	queue <int> q;
	us_ing[start]=1;
	dis[start]=0;
	q.push(start);
	while(!q.empty())
	{
		int top=q.front();
		q.pop();
		us_ing[top]=0;
		outqueue[top]++;
		if(outqueue[top]>n)	return 0;
		for(int i=head[top];i!=-1;i=edge[i].next)
		{
			if(dis[edge[i].to]>dis[top]+edge[i].w)
			{
				dis[edge[i].to]=dis[top]+edge[i].w;
				if(!us_ing[edge[i].to])
				{
					us_ing[edge[i].to]=1;
					q.push(edge[i].to);
				}
			}
		}
	}
	return 1;
}
