	template<typename T>
	vector<vector<T>> WarshalFloyd(vector<vector<T>>& path,T inf) {
		int n = path.size();
		vector<vector<int>> res = path;
		vector<vector<int>> next(n, vector<int>(n, 0));
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				next[i][j] = j;
			}
		}
		// Warshal Floyd
		for (int k = 0; k < n; ++k) {
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < n; j++) {
					if (res[i][k] != inf && res[k][j] != inf && (res[i][j] == inf || res[i][j] > res[i][k] + res[k][j])) {
						res[i][j] = res[i][k] + res[k][j];
						next[i][j] = next[i][k];
					}
				}
			}
		}
		bool negative_cycle = false;
		for (int k = 0; k < n; ++k) {
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < n; j++) {
					if (res[i][k] != inf && res[k][j] != inf && (res[i][j] == inf || res[i][j] > res[i][k] + res[k][j])) {
						negative_cycle = true;
						res[i][j] = -inf;
					}
					if (res[i][k] == -inf || res[k][j] == -inf) {
						res[i][j] = -inf;
					}
				}
			}
		}
		// iからjへの経路を復元
		/*vector<vector<vector<int>>> res(n, vector<vector<int>>(n));
		for (int i = 0; i < n; i++) {
