				for (int cur = i; cur != j; cur = next[cur][j]) {
					res.push_back(cur);
				}
			}
		}*/
		return res;
	}

	void solve() {
		IOS;
		int n, m;
		cin >> n >> m;
		int inf = INT_MAX / 2;
		vector<vector<int>> path(n, vector<int>(n, inf));
		REP(i, n) {
			path[i][i] = 0;
		}
		REP(i, m) {
			int a, b, c;
			cin >> a >> b >> c;
			//a--, b--;
			chmin(path[a][b], c);
		}
		auto d = WarshalFloyd(path, inf);
		REP(i, n) {
			REP(j, n) {
				if (d[i][j] == -inf) {
					put("NEGATIVE CYCLE");
					return;
				}
			}
		}
		REP(i, n) {
			REP(j, n) {
