    bf.E.push_back({s, t, d});
    wf.setE(s, t, d);
  }

  if (bf.find_any_negative_loop())
  {
    cout << "NEGATIVE CYCLE\n";
  }
  else
  {
    wf.calc();
    rep(i, v) rep(j, v)
    {
      if (wf.dist(i, j) == LINF)
