					if(distance[r][A[x][i].adj] > distance[r][x] + A[x][i].dis){
						distance[r][A[x][i].adj] = distance[r][x] + A[x][i].dis;
						vern.push(A[x][i].adj);
					}
				}
				ver.pop();
			}
			if(vern.empty()) break;
			ver = vern;
			count++;
		}
		if(count > V)
			pos = false;
	}

	if(!pos){
		cout<<"NEGATIVE CYCLE"<<endl;
	}else{
		for(int i=0;i<V;i++){
			for(int j=0;j<V;j++){
				if(j != 0) cout<<" ";
				if(distance[i][j] >= N)
					cout<<"INF";
				else
					cout<<distance[i][j];
			}
			cout<<endl;
		}
	}

	return 0;
}

