	//
	int v,e;
	vector<edge> G;
	vector<ll> D;
	//
	bellman(int n,int m){
		v=n;e=m;
		D.resize(v);
	}
	//
	void add_edge(int from,int to,int cost){
		G.push_back((edge){from,to,cost});
	}
	//
	vector<ll> dist(int s){
		fill(D.begin(),D.end(),1e18+7);
		D[s]=0LL;
		for(int i=0;i<v;i++){
			bool f=false;
			for(int j=0;j<e;j++){
				edge &e=G[j];
				if(D[e.from]!=1e18+7&&D[e.to]>D[e.from]+e.cost){
					D[e.to]=D[e.from]+e.cost;
					f=true;
					if(i==v-1){
						negative=false;
						break;
					}
				}
			}
			if(!negative){
				break;
			}
			if(!f){
				break;
			}
		}
		return D;
	}
	//
};
