// warshall-floyd
void warshall_floyd(std::vector<std::vector<weight>>& g) {
    int V = g.size();
    for(int k=0; k<V; ++k) {
        for(int i=0; i<V; ++i) {
            for(int j=0; j<V; ++j) {
                if(g[i][k] == INF || g[k][j] == INF) {
                    continue;
                }
                g[i][j] = std::min(g[i][j], g[i][k] + g[k][j]);
