using namespace std;
typedef vector<long> VL;
typedef vector<VL> VVL;

VVL dist;

short Warshall_Floyd(long V){
	// 頂点は 0 ~ V 
	REP(i,V+1) dist[i][i] = 0;	//初期化
	FOR(i,0,V){
		FOR(j,0,V){
			FOR(k,0,V){
				if (dist[j][i] == loINF || dist[i][k] == loINF) continue;
				dist[j][k] = MIN(dist[j][k],dist[j][i] + dist[i][k]);
				if (dist[j][j] < 0) return (-1);
			}
		}
	}
	return 0;
}

