  REP(i, E) {
    int s, t, d; cin >> s >> t >> d;
    g.add_edge(s, t, d);
  }
  AllPairsShortestPath<ll> apsp(g);
  apsp.warshall_floyd();
  if (apsp.has_negative_loop()) {
    cout << "NEGATIVE CYCLE" << endl;
  } else {
    REP(i, g.V) {
      REP(j, g.V) {
	if (apsp.dist[i][j] == INF) {
	  cout << "INF" << (j == g.V-1 ? '\n' : ' ');
	} else {
	  cout << apsp.dist[i][j] << (j == g.V-1 ? '\n' : ' ');
	}
      }
    }
  }
  return 0;
}

