                A[i][j] = min(A[i][j], A[i][k] + A[k][j]);
            }
        }
    }

    REP1(i,N){
        if(A[i][i] < 0){
            cout << "NEGATIVE CYCLE" << endl;
            return 0;
        }
    }

    REP1(i,N){
        REP1(j,N){
            cout << A[i][j] << " ";
        }
        cout << endl;
    }

    return 0;
}

