// 0-index
struct Bellman_Ford{
	struct edge{ll from, to, cost;};
	ll inf = 1e16;
	vector<edge> es;
	vector<ll> d;
	ll V,E;
	void init(ll v,ll e){
		V = v; E = e;
		d.resize(V);
	}
	void shortest_path(ll s){
		FOR(i,0,V) d[i] = inf;
		d[s] = 0;
		FOR(i,0,V){
			FOR(j,0,E){
				edge e = es[j];
				if(d[e.from]!=inf && d[e.to]>d[e.from] + e.cost){
					d[e.to] = d[e.from] + e.cost;
				}
			}
		}
	}
	bool find_negative_loop(){// all graph
		FOR(i,0,V)d[i] = 0;
		FOR(i,0,V){
			FOR(j,0,E){
				edge e = es[j];
				if(d[e.to]>d[e.from] + e.cost){
					d[e.to] = d[e.from] + e.cost;
					if(i == V-1) return true;
				}
			}
		}
		return false;
	}
	bool find_negative_loop(ll s){// from s
		ll cnt = 0;
		FOR(i,0,V)d[i]=inf;
		d[s]=0;
		while(true){
			bool update = false;
			cnt++;
			FOR(i,0,E){
				edge e = es[i];
				if(d[e.from] != inf && d[e.to]>d[e.from] + e.cost){
					d[e.to] = d[e.from] + e.cost;
					if(cnt == V){
						return true;
					}
					update = true;
				}
			}
			if(! update)break;
		}
		return false;
	}
	bool shortest_path(int s, int t){ // t: destination
		FOR(i,0,V)d[i] = inf;
		d[s] = 0;
		FOR(i,0,2*V){
			FOR(j,0,E){
				edge e = es[j];
				if(d[e.from]!=inf && d[e.to]>d[e.from] + e.cost){
					d[e.to] = d[e.from] + e.cost;
					if(i>=V-1 && e.to==t) return true;
				}
			}
		}	
		return false;
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	ll V,E;
	cin >> V >> E;
	ll d[V][V];
	FOR(i,0,V){
		FOR(j,0,V){
			d[i][j] = INF;
		}
		d[i][i] = 0;
	}
	Bellman_Ford bf;
	bf.init(V,E);
	FOR(i,0,E){
		ll a,b,c;
		cin >> a >> b >> c;
		d[a][b] = c;
		bf.es.push_back({a,b,c});
	}
	if(bf.find_negative_loop()){
		cout << "NEGATIVE CYCLE" << endl;
		return 0;
	}
	FOR(k,0,V){
		FOR(i,0,V){
			FOR(j,0,V){
				if(d[i][k]!=INF && d[k][j]!=INF)
					d[i][j] = min(d[i][j],d[i][k]+d[k][j]);
			}
		}
	}
	FOR(i,0,V){
		FOR(j,0,V){
			if(j!=0)cout << " ";
			if(d[i][j]==INF){
				cout << "INF";
			}else{
				cout << d[i][j];
			}
		}
		cout << endl;
	}

}

