static const int MAX = 100;
static const int long long INFTY = (1LL << 32);

int n;
LL d[MAX][MAX];

void floyd()
{
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (d[i][k] == INFTY) {  // d[i][k]は通らないのでスキップ
                continue;
            }
            for (int j = 0; j < n; j++) {
                if (d[k][j] == INFTY) {  // d[k][j]を通らないのでスキップ
                    continue;
                }
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);  // (i, j)への経路(前回までは最短)と,(i, k)->(k, j)を比較する
            }
        }
    }
}

