bool warshell(int n,vector<mp>* vs,vector<int>* dist,vector<int> *gone){
	rep(i,n){
		gone[i].clear();
		dist[i].clear();
		gone[i].resize(n,-1);
		dist[i].resize(n,-1);

		gone[i][i]=1;
		dist[i][i]=0;
		rep(j,vs[i].size()){
			int to=vs[i][j].fir,
				co=vs[i][j].sec;
			gone[i][to]=1;
			dist[i][to]=co;
		}
	}

	rep(k,n){
		rep(i,n){
			rep(j,n){
				if(gone[i][k]==-1 || gone[k][j]==-1)continue;
				int cd=dist[i][k]+dist[k][j];
				if(gone[i][j]==-1 || dist[i][j]>cd){
					gone[i][j]=1;
					dist[i][j]=cd;
				}
			}
		}
	}
	rep(i,n)if(dist[i][i]!=0)return false;
	return true;
}





