    int V,E;
    cin >> V >> E;
    vector<vector<ll>>dist(V,vector<ll>(V));
    rep(i,V) rep(j,V) {
        if(i==j) dist[i][j] = 0;
        else dist[i][j] = INF;
    }
    rep(i,E) {
        int a,b,c;
        cin >> a >> b >> c;
        dist[a][b] = c;
    }
    vector<vector<ll>>prev(V,vector<ll>(V));
    warshall_floyd(dist,prev);
    if(is_negative(dist)) {
        cout << "NEGATIVE CYCLE" << endl;
        return 0;
    } else {
        rep(i,V) {
            rep(j,V) {
                if(dist[i][j] >= INF/2) {
                    cout << "INF";
                } else {
                    cout << dist[i][j];
                }
                if(j != V-1) cout << " ";
            }
            cout << endl;
        }
    }
}

/**
 * 全点対間最短経路
 * ベルマン・フォード法
 * https://onlinejudge.u-aizu.ac.jp/courses/library/5/GRL/all/GRL_1_C
 * */

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
//#define INF 1LL<<60 //使いやすい無限(ll)
#define INF 1'000'000'000'000'000'000

using Node = long long; //頂点
using Distance = long long; //距離
using Weight = long long; //重み

using Edge = tuple<Node, Node, Weight>;

ll V,E;
vector<Edge> Edges;
vector<Distance> dist;

bool BellmanFord(ll start){
  dist.assign(V, INF);
  dist[start] = 0;

  for(int i=1; i<V; i++){
    for(Edge x: Edges){
      Node s,t; Weight d;
      tie(s,t,d) = x;
      if(dist[s]==INF)continue; //距離無限ノードからの辺は考えない

      if(dist[s]+d < dist[t]){
        dist[t] = dist[s] + d;
      }

    }
  }

  bool NC = false;
  for(Edge x: Edges){
    Node s,t; Weight d;
    tie(s,t,d) = x;
    if(dist[s]==INF)continue; //距離無限ノードからの辺は考えない
    if(dist[s]+d < dist[t]){
      NC = true;
    }
  }

  return NC;
}

