  for(int i=0; i<E; i++){
    ll s,t,d;
    cin>>s>>t>>d;
    Edges.push_back(make_tuple(s,t,d));
  }

  for(ll r=0; r<V; r++){
    bool isNcycle = BellmanFord(r);

    if(isNcycle){
      cout<<"NEGATIVE CYCLE"<<endl;
      return 0;
    }

    ll x = dist[0];
