void warshall_floyd() {
  for (int i = 0; i < Vnum; i++) {
    for (int j = 0; j < Vnum; j++) {
      d[i][j] = INF;
    }
    d[i][i] = 0;
  }

  for (int i = 0; i < Enum; i++) {
    auto e = edges[i];
    d[e.from][e.to] = e.cost;
  }

  for (int k = 0; k < Vnum; k++) {
    for (int i = 0; i < Vnum; i++) {
