int v,e,g[100][100],s,t,d;

int dd[100];
bool visited[100];
bool ngl;

void dfs(int n) {
    loop(i,0,v){
        if(g[n][i] != 0x7ffffff){
            if(dd[i] > dd[n] + g[n][i]) {
                dd[i] = dd[n] + g[n][i];
                if(visited[i]){ngl = true;break;}
                visited[i] = true;
                dfs(i);
                visited[i] = false;
            }
        }
    }
}

int main() {
    for(int i = 0;i < 100;i++)for(int j = 0;j < 100;j++) if(i!=j)g[i][j] = 0x7ffffff;
