int V, E;

bool warshall_floyd(int c[MAX_V][MAX_V]){
  REP(k, V)
    REP(i, V)
      REP(j, V)
        c[i][j] = min(c[i][j], c[i][k] + c[k][j]);
  REP(i, V) if(c[i][i] < 0) return false;
  return true;
}

