  REP(i, E){
    int f, t, cost; cin >>f >>t >>cost;
    c[f][t] = cost;
  }
  bool f = warshall_floyd(c);
  if(!f) cout <<"NEGATIVE CYCLE" <<endl;
  else{
    REP(i, V){
