ll Min(ll a,ll b){
    return a<b?a:b;
}

void floyd(){
    for(int k=0;k<n;k++){
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++)
                d[i][j]=Min(d[i][j],d[i][k]+d[k][j]);
        }
    }
}

