                chmin(dp[i][j], dp[i][k] + dp[k][j]);
            }
        }
    }

    bool flag = true;
    rep(i, V) if (dp[i][i] < 0) flag = false;
    if (!flag) {
        cout << "NEGATIVE CYCLE" << endl;
        return 0;
    } 
    rep(i, V) {
        rep(j, V) {
            if (dp[i][j] == INF) {
                cout << "INF";
            }
            else cout << dp[i][j];
            if (j != V - 1) cout << " ";
        }
        cout << endl;
    }
    return 0;
}

