struct node {
	bool done;
	vi to, dist;
	int id, from;
	ll d;
	bool operator<(const node & another) const {
		return !(d != another.d ? d < another.d : id < another.id);
	}
};

void bellman_ford(vector<node> nodes, int n, int start, int limit) {
	nodes[start].d = 0;
	queue<node> que;
	que.push(nodes[start]);
	int cnt = 0;
	while (que.size() && cnt<limit) {
		node focus = que.front(); que.pop();
		Loop(i, focus.to.size()) {
			if (nodes[focus.to[i]].d > focus.d + focus.dist[i]) {
				nodes[focus.to[i]].d = focus.d + focus.dist[i];
				nodes[focus.to[i]].from = focus.id;
				que.push(nodes[focus.to[i]]);
			}
		}
		cnt++;
	}
	if (cnt == limit) ans.clear();
	else {
		ans.push_back({});
		Loop(i, n) {
			ans.back().push_back(nodes[i].d);
		}
	}
}

