const ll inf = 100100100100100;

vector<vector<ll>> warshall_floyd(vector<vector<ll>> edges,int v){
    vector<vector<ll>> ret = edges;
    rep(k,0,v){
        rep(i,0,v){
            rep(j,0,v){
                if(ret[i][k] == inf || ret[k][j] == inf) continue;
                ret[i][j] = min(ret[i][j],ret[i][k] + ret[k][j]);
            }
        }
    }
    return ret;

}

