/**
 * 全ノード間の最短距離をもとめる
 * matrix[i][j]には辺e=(i,j)のコスト(辺が存在しない場合はINT_MAX)
 * O(|V|^3)
 */
std::vector<std::vector<int>> warshall_floyd(std::vector<std::vector<int>> matrix) {
    const unsigned long n = matrix.size();

    // 自分の距離は0
    for (int i = 0; i < n; ++i) {
        matrix[i][i] = 0;
    }

    for (int m = 0; m < n; ++m) {
        for (int s = 0; s < n; ++s) {
            for (int e = 0; e < n; ++e) {
                // sからeへmを経由して到達可能
                if (matrix[s][m] != INT_MAX and matrix[m][e] != INT_MAX) {
                    matrix[s][e] = std::min(matrix[s][e], matrix[s][m] + matrix[m][e]);
                }
            }
        }
    }

    return matrix;
}

using namespace std;

int main(void) {
    int V, E;
    cin >> V >> E;

    vector<vector<int>> matrix(V, vector<int>(V, INT_MAX));
    for (int i = 0; i < E; ++i) {
        int s, t, d;
        cin >> s >> t >> d;
        matrix[s][t] = d;
    }

    matrix = warshall_floyd(matrix);
    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < V; ++j) {
            if (matrix[i][j] == INT_MAX) {
                cout << "INF ";
            } else {
                cout << matrix[i][j] << " ";
            }
        }
        cout << endl;
    }

    return 0;
}

