    WarshallFloyd<ll> d(v);
    for(int i=0;i<v;i++){
        d.adbuild(i,i,0);
    }

    while(e--){
        int s,t;
        ll c;
        cin>>s>>t>>c;
        d.adbuild(s,t,c);
    }
    ll inf=numeric_limits<ll>::max();
    for(int i=0;i<v;i++){
        if(d.query(i,i)<0){
            cout<<"NEGATIVE CYCLE"<<endl;
            return 0;
        }
    }
    for(int i=0;i<v;i++){
        for(int j=0;j<v;j++){
            if(j) cout<<" ";
            if(d.query(i,j)==inf) cout<<"INF";
            else cout<<d.query(i,j);
        }
        cout<<endl;
    }
}

