// A_k :: {1, 2,..,k}のみを経由する頂点i->jの最短コスト
void floyd() {
  for (int k = 0; k < n; k++) { //すべての頂点に対して調べる
    for (int i = 0; i < n; i++) {
      if (d[i][k] == INFTY) continue;
      for (int j = 0; j < n; j++) {
        if (d[k][j] == INFTY) continue;
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
}

