int m[N][N], n;

void Floyd()
{
	for (int k = 0; k < n; ++k){
		for (int i = 0; i < n; ++i){
			if (m[i][k] == INFTY) continue;
			for (int j = 0; j < n; ++j){
				if (m[k][j] == INFTY) continue;
				m[i][j] = std::min(m[i][j], m[i][k] + m[k][j]);
			}
		}
	}
}


