	for (int i = 0; i < x; ++i)
	{
		int u, v, d;
		cin >> u >> v >> d;
		m[u][v] = d;
	}

	Floyd();

	bool neg = false;
	for (int i = 0; !neg && i < n; ++i){
			if (m[i][i] < 0) neg = true;
