class number
{
public:
	int num;
	bool is_INF;
	number(){};
	number(const int n, const bool b);
	void show_n();
};

number::number(const int n, const bool b)
{
	num = n, is_INF = b;
}

void number::show_n()
{
	if(is_INF){ printf("INF"); }
	else{ printf("%d", num); }
}

number operator+(const number n1, const number n2)
{
	number n3;
	if(n1.is_INF || n2.is_INF){
		n3.num = 0, n3.is_INF = true;
	}else{
		n3.num = n1.num + n2.num;
		n3.is_INF = false;
	}
	return n3;
}

number min_ex(const number n1, const number n2)
{
	number n3;
	if(n1.is_INF && n2.is_INF){
		n3.num = 0, n3.is_INF = true;
	}else{
		n3.is_INF = false;
		if(n1.is_INF){ n3.num = n2.num; }
		else if(n2.is_INF){ n3.num = n1.num; }
		else{ n3.num = min(n1.num, n2.num); }
	}
	return n3;
}

int main()
{
    int i, j, n, m, from, to, cost;
    scanf("%d %d", &n, &m);

