//=============warshall_floyd============================
vector<vector<long long>>  warshall_floyd(long long V, vector<vector<long long>> d)
{
  for (long long k = 0; k < V; ++k)
  {
    for (long long i = 0; i < V; ++i)
    {
      for (long long j = 0; j < V; ++j)
      {
        if (d[i][k] == INF || d[k][j] == INF)
        {
          continue;
        }
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
  return d;
}
