  {
    dist.at(i).at(i) = 0;
  }
  for (long long i = 0; i < E; ++i)
  {
    cin >> s >> t >> d;
    dist.at(s).at(t) = d;
  }
  dist = warshall_floyd(V, dist);
  for (long long i = 0; i < V; ++i)
  {
    if (dist.at(i).at(i) < 0)
