bool find_negative_cycle(int v) {
  for (int i = 0; i < v; i++) {
    if (d[i][i] < 0) return true;
  }
  return false;
}

void warshall_floyd(int v) {
  for (int k = 0; k < v; k++) {
    for (int i = 0; i < v; i++) {
      if (d[i][k] == INF) continue;
      for (int j = 0; j < v; j++) {
	if (d[k][j] == INF) continue;
	d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
}

void init(int v) {
  for (int i = 0; i < v; i++) {
    for (int j = 0; j < v; j++) {
      if (i == j) d[i][j] = 0;
      else d[i][j] = INF;
    }
  }

  for (int i = 0; i < v; i++) {
    for (int j = 0; j < G[i].size(); j++) {
      d[i][G[i][j].to] = G[i][j].cost;
    }
  }
}

