    REP(i, e) {
        int a, b, c;
        cin >> a >> b >> c;
        wf.directed_update(a, b, c);
    }
    wf.calc();
    if (wf.is_negative()) {
        print("NEGATIVE CYCLE");
        return 0;
    }
    vector<vector<string>> ans(v, vector<string>(v));
    REP(i, v) {
        REP(j, v) {
            auto dist = wf.dist(i, j);
            if (dist.second) {
                ans[i][j] = to_string(dist.first);
            } else {
                ans[i][j] = "INF";
            }
        }
    }
    print(ans);

    return 0;
}

