        edges[s].push_back({d, t});
        dm[s][t] = d;
    }

    Vl d(n, 1e18);
    unordered_set<int> toUpdate;
    toUpdate.insert(0);
    d[0] = 0;
    REP(i, n) {
        unordered_set<int> toUpdateBuf(toUpdate);
        toUpdate.clear();
        FOR(j, toUpdateBuf) {
            int node = *j;
            FOR(k, edges[node]) {
                int dist = k->second;
                ll cost = k->first;
                if (d[dist] > d[node] + cost) {
                    d[dist] = d[node] + cost;
                    toUpdate.insert(dist);
                    if (i == n - 1) {
                        cout << "NEGATIVE CYCLE" << endl;
                        return 0;
                    }
                }
            }
        }
        if (toUpdate.empty()) break;
    }

    REP(i, n) dm[i][i] = 0;

    REP(k, n) REP(i, n) REP(j, n) {
        if (dm[i][k] == 1e18 || dm[k][j] == 1e18) continue;
        dm[i][j] = min(dm[i][j], dm[i][k] + dm[k][j]);
    }

    REP(i, n) {
        REP(j, n) {
            if (dm[i][j] == 1e18) {
                std::cout << "INF";
            } else {
                std::cout << dm[i][j];
            }
            if (j != n-1) {
                std::cout << ' ';
            }
        }
        std::cout << '\n';
    }

    return 0;
}

