void floyd()
{
    for(int k=0; k<V; k++)
    {
        for(int i=0; i<V; i++)
        {
            if(G[i][k]==INF) continue;
            for(int j=0; j<V; j++)
            {
                if(G[k][j]==INF) continue;
                G[i][j] = min(G[i][j], G[i][k]+G[k][j]);
            }
        }
    }
}
bool negative()
{
    for(int i=0; i<V; i++)
    {
        if(G[i][i]<0)
            return 1;
    }
    return 0;
}
