            else G[i][j] = INF;
        }
    }
    for(int i=0; i<E; i++)
    {
        cin >> s >> t >> d;
        G[s][t] = d;
    }
    floyd();
    if(negative())
        cout << "NEGATIVE CYCLE" << endl;
    else
    {
        for(int i=0; i<V; i++)
