		for(i=0; i<n; i++)
			for(j=0; j<n; j++)
				if(dis[i][k]<inf&&dis[k][j]<inf) //必须写这个判断条件
					dis[i][j]=min(dis[i][j],dis[i][k]+dis[k][j]);
