template<size_t MAX_V>
class AdjacencyMatrix {
private:
  int w_[MAX_V][MAX_V];
  size_t size_;
public:
  AdjacencyMatrix(size_t size_)
    : size_(size_)
  {
    for(int i = 0; i < size_; ++i) {
      for(int j = 0; j < size_; ++j) {
        w_[i][j] = INF;
      }
      w_[i][i] = 0;
    }
  }
  void set(int from, int to, int w) {
    w_[from][to] = w;
  }
  int& get(int from, int to) {
    return w_[from][to];
  }
  size_t size() {
    return size_;
  }
  bool negativeclosedpath() {
    for(int i = 0; i < size_; ++i) {
      if( w_[i][i] < 0 ) {
        return true;
      }
    }
    return false;
  }
};

template<size_t MAX_V>
void WarshallFloyd(AdjacencyMatrix<MAX_V>& arg) {
  for(int k = 0; k < arg.size(); ++k) {
    for(int i = 0; i < arg.size(); ++i) {
      for(int j = 0; j < arg.size(); ++j) {
        arg.get(i, j) = Min(arg.get(i, j), arg.get(i, k) + arg.get(k, j));
      }
    }
  }
}

class Solver {
private:
public:
  void solve() {
    int V, E;
    io >> V >> E;
    AdjacencyMatrix<128> matrix(V);
    for(int i = 0; i < E; ++i) {
      int s, t, d;
      io >> s >> t >> d;
      matrix.set(s, t, d);
    }
    WarshallFloyd(matrix);
    if( matrix.negativeclosedpath() ) {
      io << "NEGATIVE CYCLE" << '\n';
    }
    else {
      for(int i = 0; i < (int)matrix.size(); ++i) {
        for(int j = 0; j < (int)matrix.size() - 1; ++j) {
          int w = matrix.get(i, j);
          if( w != INF ) {
            io << w << ' ';
          }
          else {
            io << "INF ";
          }
        }
        int w = matrix.get(i, matrix.size() - 1);
        if( w != INF ) {
          io << w << ' ';
        }
        else {
          io << "INF ";
        }
      }
    }
    return;
  }
};

