ll A[MAX_N][MAX_N]; int n;

void init(){
    rep(i,MAX_N){
        rep(j,MAX_N){
            A[i][j] = (i == j ? 0: INF);
        }
    }
}

void warshallFloyd(){
    rep(k,n){
        rep(i,n){
            rep(j,n){
                A[i][j] = min(A[i][j], A[i][k]+A[k][j]);
            }
        }
    }
}

bool isNegative(){
    rep(i,n){
        rep(j,n){
            if(i == j && A[i][j] < 0) return true;
        }
