int main(void) {
    int V, E;
    cin >> V >> E;

    vector<vector<int>> matrix(V, vector<int>(V, INT_MAX));
    for (int i = 0; i < E; ++i) {
        int s, t, d;
        cin >> s >> t >> d;
        matrix[s][t] = d;
    }

    matrix = warshall_floyd(matrix);
    if (matrix.empty()) {
        cout << "NEGATIVE CYCLE" << endl;
        return 0;
    }

    for (int i = 0; i < V; ++i) {
        for (int j = 0; j < V; ++j) {
            if (matrix[i][j] == INT_MAX) {
                cout << "INF ";
            } else {
                cout << matrix[i][j] << " ";
            }
        }
        cout << endl;
    }

    return 0;
}

