        {
            cout << "NEGATIVE CYCLE\n";
            return;
        }
    }
    // output
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            if (dp[i][j] == INFLL)
            {
                cout << "INF";
