void initialFromGraphList_Cost(std::vector<std::vector<edge>>& G, std::vector<std::vector<long long>>& d){
    int V(G.size());
    d.resize(V);
    for(int i(0); i < V; ++i){
        d[i].resize(V, LINF);
        d[i][i] = 0;
    }
    for(int i(0); i < V; ++i){
        for(auto& e: G[i])
            d[i][e.to] = e.cost;
    }
