void warshallFloyd(std::vector<std::vector<long long>>& d){
    int V(d.size());
    for(int k(0); k < V; ++k)
        for(int i(0); i < V; ++i)
            for(int j(0); j < V; ++j)
                chmin(d[i][j], d[i][k] + d[k][j]);
}

