    rep(i, N) E[i].push_back(Edge(i, 0));
    auto dist = warshall_floyd(E);
    rep(i, N) {
        rep(j, N) cout << (dist[i][j] < INFL ? to_string(dist[i][j]) : "INF") << (j == N - 1 ? "\n" : " ");
    }
    return 0;
}

