			return (*this);
		}
	}
	Edge operator+(const Edge &other){
		if (exist and other.is_exist()){
			return (Edge(distance + other.distance));
		}else{
			return (Edge(false));
		}
	}
	const bool operator>(const Edge &other){
		if (other.exist){
			if (exist){
				return distance > other.distance;
			}else{
				return true;
			}
		}else{
			return false;
		}
	}
	const bool operator<(const int &d){return (distance < d);}
private:
	bool exist;
	int distance;
};
int main(){
	int v, e;
	std::scanf("%d %d", &v, &e);
	std::vector<std::vector<Edge>> vertex(v, std::vector<Edge>(v));
	for (auto i = 0; i < e; ++i){
		int s, t, d;
		std::scanf("%d %d %d", &s, &t, &d);
		vertex.at(s).at(t) = d;
	}
	for (auto i = 0; i < v; ++i){
		vertex.at(i).at(i) = 0;
	}
	for (auto k = 0; k < v; ++k){
		for (auto i = 0; i < v; ++i){
			for(auto j = 0; j < v; ++j){
				if (vertex.at(i).at(j) > (vertex.at(i).at(k) + vertex.at(k).at(j))){
					vertex.at(i).at(j) = vertex.at(i).at(k) + vertex.at(k).at(j);
				}
			}
		}
		//express(vertex);
	}
	bool negative = false;
	for (auto i = 0; i < v; ++i){
		if (vertex.at(i).at(i) < 0){
			negative = true;
		}
	}
	if (negative){
		std::printf("%s", "NEGATIVE CYCLE");
	}else{
		for (auto i = 0; i < v; ++i){
			if (vertex.at(i).at(0).is_exist()){
