  FOR(i,0,E){
    cin>>WF.a[i]>>WF.b[i]>>WF.c[i];
  }
  WF.calc();
  FOR(i,0,V){
    if(WF.dist[i][i]<0){
      cout<<"NEGATIVE CYCLE"<<endl;
      return 0;
    }
  }
  FOR(i,0,V) {
    FOR(j,0,V) {
      if(j) cout<<" ";
      if(WF.dist[i][j]==(1<<31)-1) cout<<"INF";
      else cout<<WF.dist[i][j];
    }
    cout<<endl;
  }
}

