	long long n,m,r,a,b,c;
	cin>>n>>m;
	for(int i=0;i<m;i++){
		cin>>a>>b>>c;
		x[a].push_back(b*TEISU+c);
	}
	for(int h=0;h<n;h++){
		_memset();
		r=h;
		Q.push(r);
		for(int i=0;i<MAX_N;i++){color[i]=WHITE;d[i]=INF;}
		d[r]=0;color[r]=GRAY;
		dijkstra();
		for(int i=0;i<n;i++){if(i){cout<<' ';}if(d[i]==INF){cout<<"INF";}else{cout<<d[i];}}
