class WarshallFloyd {
private:
    int m_V;                   
    vector<vector<int>> m_d;

public:
    const int INF = INT_MAX / 2;

    WarshallFloyd(int V) {
        m_V = V;

        // ???????????????????????????
        // ???????????¨???????????¨??????INF??¨??????
        m_d.resize(m_V, vector<int>(m_V, INF));
        REP(i,V) m_d[i][i] = 0;
    }

    void add_dir_edge(int from, int to, int cost) {
        m_d[from][to] = cost;
    }

    void add_undir_twoways(int v1, int v2, int cost) {
        add_dir_edge(v1, v2, cost);
        add_dir_edge(v2, v1, cost);
    }

    // ??¨????????????????????¢????±???????
    vector<vector<int>> shortest_path() {
        REP(k, m_V){
            REP(i, m_V){
                REP(j, m_V){
                    m_d[i][j] = min(m_d[i][j], m_d[i][k] + m_d[k][j]);
                }
            }
        }
        return m_d;
    }

    // shortest_path?????????????????¨????????¶?????¨
    bool has_negative_loop() {
        REP(i, m_V) {
            if (m_d[i][i] < 0) return true;
        }
        return false;
    }
};


