    int INF;

    WarshallFloyd(int V)
        : INF(INT_MAX/2)
        , m_V(V) {

        // ???????????????????????????
        // ???????????¨???????????¨??????INF??¨??????
        m_d.resize(m_V, vector<int>(m_V, INF));
        REP(i,V) m_d[i][i] = 0;
    }

