        }
    }
}

void wf_run(int V) {
    for (int k = 0; k < V; ++k) {
        for (int i = 0; i < V; ++i) {
            if (dist[i][k] == INF) {
                continue;
            }
            for (int j = 0; j < V; ++j) {
                if (dist[k][j] == INF) {
                    continue;
                }
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

bool has_negcycle(int V) {
    for (int i = 0; i < V; ++i) {
        if (dist[i][i] < 0) return true;
