pair<bool,vector<vector<i64>>> graph_floyd(vector<vector<i64>>& g) {
    i64 n = SIZE(g);
    vector<vector<i64>> nex(n, vector<i64>(n,-1));
    REP(i, n) REP(j, n) {
        if(g[i][j] != INF)
            nex[i][j] = j;
    }

    REP(k, n) {
        REP(i, n) {
            if(g[i][k] == INF) continue;
            REP(j, n) {
                if(g[k][j] == INF) continue;
                if(chmin(g[i][j], g[i][k] + g[k][j])) {
                    nex[i][j] = nex[i][k];
                }
                if(i == j && g[i][j] < 0) return { false, nex };
            }
        }
    }

    return { true, nex };
}

void solve() {
    i64 N; RD(N);
    i64 M; RD(M);

    vector<vector<i64>> G(N, vector<i64>(N, INF));
    REP(i, N) {
        G[i][i] = 0;
    }
    REP(_, M) {
        i64 from,to; RD(from); RD(to);
        i64 cost; RD(cost);
        G[from][to] = cost;
    }

    bool ok;
    tie(ok,ignore) = graph_floyd(G);
    if(!ok) {
        PRINTLN("NEGATIVE CYCLE");
        return;
    }

    REP(i, N) {
        REP(j, N) {
            if(G[i][j] == INF)
                PRINT("INF");
            else
                PRINT(G[i][j]);
            if(j != N-1) PRINT(' ');
        }
        PRINTLN();
    }
}

signed main() {


    solve();

    EXIT();
}

