	cin>>N>>M;
	cMatrixRepEdges Edges(N,vector<int>(N,INT_MAX));
	for(int i=0;i<M;++i){
		int u,v,w;
		cin>>u>>v>>w;

		Edges[u][v]=w;
		//Edges[u].push_back(v);
	}

