int V,E;
llong M[MAX+1][MAX+1];

void deal(){
    for(int k=0;k<V;k++){
        for(int i=0;i<V;i++){
            if(M[i][k]==MINVAL) continue;
            for(int j=0;j<V;j++){
                if(M[k][j]==MINVAL) continue;
                M[i][j]=min(M[i][j],M[i][k]+M[k][j]);
            }
        }
    }
}

int main(){
    cin>>V>>E;
    for(int i=0;i<V;i++){
