#define MAX 100000

struct edge{
    int s,t,d;
};

vector<edge> edges;
string ans;
int d[MAX];

int BellmanFord(int startVertex,int vNum,int eNum){
    fill((int*)d,(d + MAX),__INT_MAX__);
    d[startVertex] = 0;

    for(int i = 0;i < vNum;++i){
        bool update = false;
        for(int j = 0;j < eNum;++j){
            edge e = edges[j];
            if(d[e.s] != __INT_MAX__ && d[e.t] > d[e.s] + e.d){
                d[e.t] = d[e.s] + e.d;
                update = true;
                if(i == vNum - 1){
                    cout<<"NEGATIVE CYCLE"<<endl;
                    return - 1;
                }
            }
        }
        if(!update)break;
    }
    for(int i = 0;i < vNum;++i){
        if(i > 0) ans.append(" ");
        if(d[i]==__INT_MAX__){
            ans.append("INF");
        }
        else{
            stringstream ss;
            ss << d[i];
            ans.append(ss.str());
        } 
    }
    return 0;
}

