template<typename T>
void warshall_floyd(Matrix<T>& g, T INF) {
    for(i32 k = 0; k < SZ(g); k++) {
        for(i32 i = 0; i < SZ(g); i++) {
            for(i32 j = 0; j < SZ(g); j++) {
                if(g[i][k] == INF || g[k][j] == INF) continue;
                g[i][j] = std::min(g[i][j], g[i][k] + g[k][j]);
            }
        }
    }
}

