  REP(i, E) {
    int src, dst, weight;
    cin >> src >> dst >> weight;
    g.add_edge(src, dst, weight);
  }

  AllPairsShortestPath alsp(g);

  alsp.warshall_floyd();

  if (alsp.has_negative_loop()) {
    cout << "NEGATIVE CYCLE" << endl;
  } else {
    REP(i, V) {
      REP(j, V) {
	if (alsp.g.Adj[i][j] == INF) {
	  cout << "INF" << (j == V-1 ? '\n' : ' ');
	} else {
	  cout << alsp.g.Adj[i][j] << (j == V-1 ? '\n' : ' ');
	}
      }
    }
  }  
  return 0;
}

