bool Visitable[105][105];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int V, E;
    cin >> V >> E;
    constexpr ll inf = 1e+15;
    vector<vector<ll>> dp(V, vector<ll>(V, inf));
    vector<tuple<int, int, int>> es;
    for(int i = 0; i < E; ++i){
        int s, t, d;
        cin >> s >> t >> d;
        dp[s][t] = d;
        Visitable[s][t] = true;
        es.emplace_back(s, t, d);
    }

    vector<ll> dist(V, 0);
    for(int i = 0; i < V; ++i){
        bool update = false;
        for(auto tup : es){
            int s, t, d;
            tie(s, t, d) = tup;
            if(chmin(dist[t], dist[s] + d)) update = true;
        }
        if(i == V - 1 && update){
            cout << "NEGATIVE CYCLE\n";
            return 0;
        }
    }

    for(int i = 0; i < V; ++i){
        dp[i][i] = 0;
        Visitable[i][i] = true;
    }
    for(int k = 0; k < V; ++k){
        for(int i = 0; i < V; ++i){
            for(int j = 0; j < V; ++j){
                chmin(dp[i][j], dp[i][k] + dp[k][j]);
                Visitable[i][j] |= Visitable[i][k] & Visitable[k][j];
            }
        }
    }

    for(int i = 0; i < V; ++i){
        for(int j = 0; j < V; ++j){
            if(Visitable[i][j]) cout << dp[i][j];
            else    cout << "INF";
            cout << ((j == V - 1) ? '\n' : ' ');
        }
    }
}

