                C[i][j] = std::min(C[i][j], C[i][k] + C[k][j]);
            }
        }
    }

    bool cycle = false;
    REP(i, N) {
        if (C[i][i] < 0)
            cycle = true;
    }

    if (cycle)
        cout << "NEGATIVE CYCLE" << endl;
    else {
        REP(i, N) {
            REP(j, N) {
                if (C[i][j] == INF)
                    cout << "INF";
                else
                    cout << C[i][j];

                if (j < N - 1)
                    cout << " ";
            }
            cout << endl;
        }
    }
    return 0;
}

