    cin >> v >> e;
    Graph gr(v, true);
    REP(i,e){
        cin >> s >> t >> d;
        gr.connect(s,t,d);
    }
    ll inf = 1LL<<62;
    std::vector<std::vector<ll>> ans = WarshallFloyd(gr, inf);
