    REP(i,v)if(ans[i][i]!=0)negative=true;
    if(negative){cout<< "NEGATIVE CYCLE"<<endl; return 0;}
    for(auto i : ans){
        REP(j,v){
            if(i[j]==inf) cout << "INF";
            else cout << i[j];
            if(j!=v-1)cout << " ";
            else cout << endl;
        }
    }
}

