int main(void)
{
    using namespace std;
    using namespace graph;

    int n, e, u, v, c;
    cin >> n >> e;
    matrix_t W(n, array_t(n, limits::inf));
    for (int i = 0; i < n; i++) { W[i][i] = 0; }

    for (int i = 0; i < e; i++) {
        cin >> u >> v >> c;
        W[u][v] = c;
    }

    matrix_t D = floydwarshall(W);

    bool neg = false;
    for (int i = 0; i < n; i++) { if (D[i][i] < 0) { neg = true; } }

    if (neg) {
        cout << "NEGATIVE CYCLE" << endl;
    }
    else {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j) cout << " ";
                if (D[i][j] == limits::inf) cout << "INF";
                else                        cout << D[i][j];
            }
            cout << endl;
        }
    }

    return 0;
}

