void solve(){
    // main algorithm
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            for (int k = 0; k < N; ++k)
            {
                dp[k][j] = min(dp[k][j], dp[k][i] + dp[i][j]);
            }
        }
    }
}
