void answer(){
    // output answer
    // check negative cycle
    for (int i = 0; i < N; ++i)
    {
        if (dp[i][i] < 0)
        {
            cout << "NEGATIVE CYCLE\n";
            return;
        }
    }
    // output
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            if (dp[i][j] == INFLL)
            {
                cout << "INF";
            }else{
                cout << dp[i][j];
            }
            if(j != N) cout << " ";
        }
        cout << endl;
    }
}
