		for(int i = 0; i < G.size(); i++)
			for(int j = 0; j < G.size(); j++)
				G[i][j] = i == j ? 0 : INF;
	}

	void addEdge(int start, int end, int cost){
		G[start][end] = cost;
	}

	int dist(int start, int end){
		return G[start][end];
	}

