void initialize() {
  fill_n(&dp[0][0], MAX_V * MAX_V, INF);
  for (int i{}; i < MAX_V; ++i) dp[i][i] = 0;
}

bool warshall_floyd() {
  for (int k{}; k < V; ++k) {
    for (int i{}; i < V; ++i) {
      for (int j{}; j < V; ++j) {
        if (dp[i][k] != INF && dp[k][j] != INF) {
          dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
        }
      }
      if (dp[i][i] < 0) {
        return false;
      }
    }
  }

  return true;
}

