//constexpr ll INF = 1LL << 32;
constexpr int INF = numeric_limits<int>::max();

int V;
int E;
//vector<vector<vector<ll>>> dp;
vector<vector<vector<int>>> dp;

void warshallfloyd()
{
    FOR(k, 0, V) {
        REP(i, V) {
            REP(j, V) {
                if(dp[k][i][k] == INF || dp[k][k][j] == INF) {
                    dp[k+1][i][j] = dp[k][i][j];
                }
                else {
                    dp[k+1][i][j] = min(dp[k][i][j], dp[k][i][k] + dp[k][k][j]);
                }
            }
        }
    }
}

void solve()
{
    warshallfloyd();

    bool ok = true;
    REP(v, V) {
        if(dp[V][v][v] < 0) ok = false;
    }

    if(!ok) {
        cout << "NEGATIVE CYCLE" << "\n";
    }
    else {
        REP(i, V) {
            REP(j, V) {
                //ll d = dp[V][i][j];
                int d = dp[V][i][j];
                if(d == INF) {
                    cout << "INF";
                }
                else {
                    cout << d;
                }
                cout << (j == V-1 ? "\n" : " ");
            }
        }
    }
}

int main()
{
    cin >> V >> E;
    dp.resize(V+1);
    for(auto& mat : dp) {
        mat.resize(V);
        for(auto& row : mat) {
            row.resize(V);
        }
    }

    REP(from, V) {
        REP(to, V) {
            dp[0][from][to] = (from == to ? 0 : INF);
        }
    }

    REP(_, E) {
        int s, t, d;
        cin >> s >> t >> d;
        dp[0][s][t] = d;
    }

    solve();

    return 0;
}

