	rep(i,0,V)
	{
		fill(d[i], d[i] + MAXV, INF);
		d[i][i] = 0;
	}
	rep(i,0,E)
	{
		edge e = eg[i];
		d[e.from][e.to] = e.cost;
	}
	rep(k,0,V)
	{
		rep(i,0,V)
		{
			rep(j,0,V)
			{
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
			if (d[i][i] < 0) {
				cout << NEGATIVE << endl;
				return;
			}
		}
	}
	rep(i,0,V)
	{
		rep(j,0,V)
