template<class T=ll>struct Dijkstra:Graph<T>{
	using Graph<T>::Graph;
	Dijkstra(int N=1):Graph<T>::Graph(N){}
	const T mval=numeric_limits<T>::max()/2;
	vector<T>dist(ll s){
		vector<T> ret(this->n,mval);
		priority_queue<tuple<T,ll>> q;
		q.emplace(T(),s);
		while(!q.empty()){
			T c; ll p; tie(c,p)=q.top(); q.pop();
			if(ret[p]!=mval)continue;
			ret[p]=c=-c;
			for(auto&e:this->edge[p]){
				ll nxt;T cost;
				tie(nxt,cost)=e;
				if(ret[nxt]<=ret[p]+cost)continue;
				q.emplace(-ret[p]-cost,nxt);
			}
		}
		return ret;
	}
	T dist(ll s,ll t){return dist(s)[t];}
};

template<class T=ll>struct BellmanFord:Graph<T>{
	using Graph<T>::Graph;
	BellmanFord(int N=1):Graph<T>::Graph(N){}
	const T mval=numeric_limits<T>::max()/2;
	vector<T>dist(ll s){
		vector<T> ret(this->n,mval);
		ret[s]=0;
		rep(i,2*this->n){
			rep(f,this->n)for(auto&e:this->edge[f]){
				ll t; T c; tie(t,c)=e;
				if(ret[f]!=mval && chmin(ret[t],ret[f]+c) && i+1>=this->n){
					ret[t]=-mval;
				}
			}
		}
		return ret;
	}
	T dist(ll s,ll t){return dist(s)[t];}
};

template<class T=ll>struct WarshallFloyd:Graph<T>{
	using Graph<T>::Graph;
	WarshallFloyd(int N=1):Graph<T>::Graph(N){}
	const T mval=numeric_limits<T>::max()/2;
	vector<vector<T>>dist(){
		vector<vector<T>> ret(this->n,vector<T>(this->n,mval));
		rep(i,this->n)ret[i][i]=0;
		rep(f,this->n)for(auto&e:this->edge[f]){
			ll t; T c; tie(t,c)=e; ret[f][t]=c;
		}
		rep(k,this->n)rep(i,this->n)if(ret[i][k]!=mval)
			rep(j,this->n)if(ret[k][j]!=mval)
				chmin(ret[i][j],ret[i][k]+ret[k][j]);
		return ret;
	}
};


int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n,m;
	cin>>n>>m;
	WarshallFloyd<> g(n);
	rep(i,m){
		ll a,b,c;
		cin>>a>>b>>c;
		g.add(a,b,c,true);
	}
	auto ans=g.dist();
	rep(i,n)if(ans[i][i]<0){
		puta("NEGATIVE CYCLE");
		return 0;
	}
	rep(i,n){
		vs s;
		rep(j,n)s.push_back(ans[i][j]==g.mval?"INF":to_string(ans[i][j]));
		puta(s);
	}
	return 0;
}

//
// 全頂点対間最短路を求める、Floyd-Warshall のアルゴリズム
//
// cf.
//
//
// verified:
//   AOJ Course GRL_1_C Shortest Path - All Pairs Shortest Path
//     http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_1_C&lang=jp
//


/*
    dp[a][b] := a から　b への距離

 として初期化しておいて、アルゴリズム終了後には

    dp[a][b] := a から　b への最短距離

 が格納される。注意点として、初期化時に dp[a][a] = 0 となるようにする必要がある。
 なお負閉路判定に用いることもできて、

 - 負閉路がなければ、任意の頂点 a に対して dp[a][a] = 0
 - 負閉路があったら、ある頂点 a に対して dp[a][a] < 0

 */


#include <iostream>
#include <vector>
using namespace std;
const int INF = 1<<29;

int main() {
    int V, E; cin >> V >> E;

    // initialization of Floyd-Warshall
    vector<vector<int> > dp(V, vector<int>(V, INF));
    for (int i = 0; i < V; ++i) dp[i][i] = 0;  // necessary

    // input
    for (int e = 0; e < E; ++e) {
        int a, b, w; cin >> a >> b >> w;
        dp[a][b] = w;
    }

    // Floyd-Warshall
    for (int k = 0; k < V; ++k)
        for (int i = 0; i < V; ++i)
            for (int j = 0; j < V; ++j)
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);

    // output
    bool isnegative = false;
    for (int v = 0; v < V; ++v) if (dp[v][v] < 0) isnegative = true;
    if (isnegative) puts("NEGATIVE CYCLE");
    else {
        for (int i = 0; i < V; ++i) {
            for (int j = 0; j < V; ++j) {
                if (dp[i][j] < INF) cout << dp[i][j];
                else cout << "INF";
                if (j != V-1) cout << " ";
            }
            cout << endl;
        }
    }
}

