	int path[100][100];
	cin >> V >> E;
	for (int i = 0; i < V; ++i)
	{
		for (int j = 0; j < E; ++j)
		{
			dist[i][j] = i == j ? 0 : INF;
			path[i][j] = -1;
		}
	}
