constexpr ll LINF = 0x3f3f3f3f'3f3f3f3fLL;

ll mcos[101][101];

bool floyd(int n)
{
    rep(k, n) {
        rep(i, n) {
            if (mcos[i][k] == LINF)
                continue;
            rep(j, n)
                mcos[i][j] = min(mcos[i][j], mcos[i][k] + mcos[k][j]);
        }
    }

    rep(i, n) {
        if (mcos[i][i] < 0) return (true); //negative
    }

    return (false);
}

