#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

std::vector<std::vector<long long>>
warshall_floyd(std::vector<std::vector<long long>> dist) {
  const long long LINF = 1000000000000000018LL;
  int n = (int)dist.size();
  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      if (dist[i][k] == LINF) {
        continue;
      }
      for (int j = 0; j < n; j++) {
        if (dist[k][j] == LINF) {
          continue;
        }
        dist[i][j] = std::min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }
  return dist;
}

int main() {
  const long long LINF = 1000000000000000018LL;
  int v, e;
  cin >> v >> e;
  std::vector<std::vector<long long>> mat(v, std::vector<long long>(v, LINF));
  for (int i = 0; i < v; i++) {
    for (int j = 0; j < v; j++) {
      mat[j][i] = (i == j ? 0 : LINF);
    }
  }
  while (e--) {
    int s, t, d;
    cin >> s >> t >> d;
    mat[s][t] = d;
  }

  std::vector<std::vector<long long>> dist = warshall_floyd(mat);
  for (int i = 0; i < v; i++) {
    if (dist[i][i] < 0) {
      cout << "NEGATIVE CYCLE" << endl;
      return 0;
    }
  }
  for (int i = 0; i < v; i++) {
    for (int j = 0; j < v; j++) {
      if (dist[i][j] != LINF) {
        cout << dist[i][j];
      } else {
        cout << "INF";
      }
      cout << (j == v - 1 ? "\n" : " ");
    }
  }
  return 0;
}

// Warshall-Floyd  algorithm 
// reference Programming Contest Challenge Book Second Edition
// verify https://onlinejudge.u-aizu.ac.jp/courses/library/5/GRL/1/GRL_1_B
#include<iostream>
#include<vector>
#include<algorithm>

using namespace std;

#define rep(i,n) for(int i=0;i<(n);i++)

template<typename T> struct Warshall_Froyd {
  vector<vector<T>> G;
  int V;
  T INF;

  Warshall_Froyd(int V_,T INF_ = 1e9) {
    init(V_,INF_);
  }

  void init (int V_,T INF_ = 1e9) {
    V = V_;
    INF = INF_;

    G.resize(V,vector<T>(V,INF_));
    rep(i,V)G[i][i] = 0;
  }

  void add_edge_directed(int from,int to,T cost) {
    G[from][to] = cost;
  }

  void add_edge_non_directed(int from,int to,T cost) {
    G[from][to] = G[to][from] = cost;
  }

  vector<vector<T>> shortest_path() {
    rep(k,V) {
      rep(i,V) {
        rep(j,V) {
          G[i][j] = min(G[i][k] + G[k][j],G[i][j]);
        }
      }
    }

    return G;
  }
};

using ll = long long;


int main() {
  int V,E;
  cin >> V >> E;
  ll INF = 1e18;
  Warshall_Froyd<ll> wf(V,INF);

  rep(i,E) {
    ll s,t,d;
    cin >> s >> t >> d;
    wf.add_edge_directed(s,t,d);
  }

  vector<vector<ll>> d = wf.shortest_path();

  rep(i,V) {
    if(d[i][i] != 0){
      cout << "NEGATIVE CYCLE" << endl;
      return 0;
    }
  }
  rep(i,V) {
    rep(j,V) {
      if(d[i][j] < INF / 2)cout << d[i][j];//負の辺があるとINFより小さくなることがある
      else cout << "INF";
      cout << ((j < V - 1) ? " " : "");
    }
    cout << endl;
  }
  return 0;
}

