const long long INF = 1LL<<60;
const int MAX_N = 310;
// 頂点数，辺数
int N, M;
// dp 配列 (INF で初期化します)
vector<vector<long long> > dp(MAX_N, vector<long long>(MAX_N, INF));

void Warshall_Floyd_init(){
    for (int v = 0; v < MAX_N; ++v) dp[v][v] = 0;
    // dp 遷移 (Floyd--Warshall)
    for (int k = 0; k < N; ++k){
        for (int i = 0; i < N; ++i){
            for (int j = 0; j < N; ++j){
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
            }
        }
    }
}


