        dp[a][b] = w;
    }

    Warshall_Floyd_init();

    // 結果出力
    // もし dp[v][v] < 0 なら負閉路あり
    bool exist_negative_cycle = false;
    for (int v = 0; v < N; ++v) if (dp[v][v] < 0) exist_negative_cycle = true;
