// WarshallFloyd法 //
template <class TCost>
void WarshallFloyd(vevector<TCost> &cost)
{
	size_t n = cost.size();
	REP(k, n) REP(i, n) REP(j, n)
	{
		if (cost[i][k] != inf<TCost>() && cost[k][j] != inf<TCost>())
		{
			cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j]);
		}
	}
}

