void solve()
{
	READ(int, V, E);
	vevector<llong> graph(V, V, inf<llong>());
	REP(i, V)
	{
		graph[i][i] = 0;
	}

	REP(i, E)
	{
		READ(int, s, t, d);
		graph[s][t] = d;
	}

	WarshallFloyd(graph);

	bool negativeCycle = false;
	REP(i, V) { negativeCycle |= graph[i][i] < 0; }

	if (negativeCycle)
	{
		WRITE("NEGATIVE CYCLE");
	}
	else
