				{
					printf("\n");
				}
				else
				{
					printf(" ");
				}
			}
		}
	}
}

#include <bits/stdc++.h>
using namespace std;
#define rep(i, n) for (int i = 0; i < n; i++)

const long INF = 1e12;

int n, m, r; // 頂点の数、辺の数、始点
bool negative;

struct edge {int from, to, cost;}; // 辺の始点・終点・重み

vector<vector<int>> adj_matrix; // 隣接行列
vector<vector<edge>> adj_list; // 隣接リスト
vector<edge> edges;

vector<long> dist; // 各頂点の始点からの最短距離（ダイクストラ用）
vector<vector<long>> dist_w; // 各頂点の始点からの最短距離（ワーシャルフロイド用）
vector<bool> visited; // 各頂点の訪問状況
vector<bool> connected; // 各頂点の始点からの連結性

void dijkstra(int start) { // 始点から各頂点までの最短距離を求めるダイクストラ法
    dist.resize(n);
    visited.resize(n);
    rep(i, n) {
        if (i == start) dist[i] = 0;
        else dist[i] = INF;
        visited[i] = false;
    }
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    pq.push({dist[start], start});
    while (not pq.empty()) {
        int cur = pq.top().second;
        pq.pop();
        visited[cur] = true;
        for (edge e : adj_list[cur]) {
            // int adj = e.to;
            if (visited[e.to] == false) {
                if (dist[e.to] > dist[e.from] + e.cost) {
                    dist[e.to] = dist[e.from] + e.cost;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
    }
}

void dfs(int start) { // 始点からの経路が存在するか判定する
    connected[start] = true;
    for (edge e : adj_list[start]) {
        if (connected[e.to] == false) {
            dfs(e.to);
        }
    }
}

void bellman_ford(int start) { // 負の重みをもつ辺がある場合に単一始点最短距離を求めるベルマンフォード法
    connected.resize(n, false);
    dist.resize(n, INF);
    dfs(start);
    dist[start] = 0;
    negative = false;
    rep(i, n) { // 頂点の数n回ループ
        for (edge e : edges) {
            if (connected[e.from] == false) continue; // 始点からの経路が存在しなければスルー
            if (dist[e.to] > dist[e.from] + e.cost) {
                dist[e.to] = dist[e.from] + e.cost;
                if (i == n - 1) {
                    negative = true; // nループ目でdistの更新が生じるとき、負の閉路が存在
                    break;
                }                
            }
        }
    }
    if (negative) {
        cout << "NEGATIVE CYCLE" << endl;
    } else {
        rep(i, n) {
            if (dist[i] == INF) cout << "INF" << endl;
            else cout << dist[i] << endl;
        }
    }
}

void warshall_floyd() { // 各頂点間の最短距離を求めるワーシャルフロイド法
    negative = false;
    rep(i, n) {
        dist_w[i][i] = 0;
    }
    rep(k, n) {
        rep(i, n) {
            rep(j, n) {
                if (dist_w[i][k] == INF || dist_w[k][j] == INF) continue;
                dist_w[i][j] = min(dist_w[i][j], dist_w[i][k] + dist_w[k][j]);
            }
        }
    }
    rep(i, n) {
        if (dist_w[i][i] < 0) {
            negative = true;
            break;
        }
    }
    if (negative) {
        cout << "NEGATIVE CYCLE" << endl;
    } else {
        rep(i, n) {
            rep(j, n) {
                if (dist_w[i][j] == INF) cout << "INF";
                else cout << dist_w[i][j];
                if (j != n - 1) cout << " ";
                else cout << endl;
            }
        }
    }
}

