		std::cout << "NEGATIVE CYCLE\n";
	} else {
		for (auto i : dist) {
			for (long long j = 0; j < V - 1; j++) {
				if (i[j] == LLONG_MAX) std::cout << "INF ";
				else std::cout << i[j] << ' ';
			}
			if (i.back() == LLONG_MAX) std::cout << "INF\n";
			else std::cout << i.back() << '\n';
		}
	}
}

