  REP(i,V) dist[i][i]=0;
  REP(i,V) for(Edge e:graph[i]) dist[e.s][e.t]=e.d;
  REP(i,V) REP(j,V) REP(k,V) {
    if(dist[i][j]>dist[i][k]+dist[k][j]){
      dist[i][j]=dist[i][k]+dist[k][j];
    }
  }
  REP(i,V) if(dist[i][i]<0) hasNegativeCycle=true;
  return {hasNegativeCycle,dist};
}

