int d[100][100];

void warshallFloyd() {
	rep(k, V) {
		rep(i, V) {
			rep(j, V) {
				if (  d[i][k] == INF || d[k][j] == INF) continue;
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}

bool findNegativeLoop() {
	warshallFloyd();
	rep(i, V)if (d[i][i] < 0) return true;
	return false;
}

