//If a graph has a closed path, it returns true.
bool bellmanford(int n, int start){
    dist = vector<int>(n,INF);
    prv  = vector<int>(n,-1);
    dist[start] = 0;
    for(int i=0; i<n+1; i++){
        for(int v=0; v<n; v++){
            for(edge e : graph[v]){
                if(dist[v]==INF || dist[v] + e.cost >= dist[e.to]) continue;
                dist[e.to] = dist[v] + e.cost;
                prv[e.to] = v;
                if(i == n) return true;
            }
        }
    }
    return false;
}

