//G[i][i] = 0 ; if G[i][i] < 0 -> G has negative cycles
//check!!! infll
template <typename T>
void Warshall_Floyd(Matrix<T> &g, T INF)
{
    int N = g.size();
    for (int k = 0; k < N; k++)
    {
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < N; j++)
            {
                if (g[i][k] == INF || g[k][j] == INF)
                    continue;
                g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
            }
        }
    }
}

int main()
{
