        mat[i][i] = 0;
    for (int i = 0; i < E; i++)
    {
        int x, y, z;
        scanf("%d %d %d", &x, &y, &z);
        mat[x][y] = z;
    }
    Warshall_Floyd(mat, INT_MAX);
    for (int i = 0; i < V; i++)
    {
        if (mat[i][i] < 0)
        {
            puts("NEGATIVE CYCLE");
            return 0;
        }
