using namespace std;

typedef long long llong;

int V, E, S[500010], T[500010], D[500010];
int C[100010];
int A[110][110];

bool bellman_ford(int r)
{
  REP(i,V)
    C[i] = INFTY;
  C[r] = 0;
  int j;
  for(j = 0; j < V; j++)
  {
    bool update = false;
    REP(i,E)
    {
      int s = S[i], t = T[i], d = D[i];
      if(C[s] < INFTY && C[s] + d < C[t])
      {
        C[t] = C[s] + d;
        update = true;
      }
    }
    if(!update) break;
  }
  return j == V;
