class WAR_FLY {
public:
    vector<vector<ll> > d; //辺の数
    ll V; //頂点の数

    WAR_FLY(ll n) {
        V = n;
        d = vector<vector<ll> > (n,vector<ll>(n));
        for(ll i = 0; i < V; i++) {
            for(ll j = 0; j < V; j++) {
                if(i == j) {
                    d[i][j] = 0;
                }
                else {
                    d[i][j] = LLINF;
                }
            }
        }
    }

    void warshall_floyd() {
        for(ll k = 0; k < V; k++) {
            for(ll i = 0; i < V; i++) {
                for(ll j = 0; j < V; j++) {
                    d[i][j] = min((ll)d[i][j], (ll)d[i][k] + (ll)d[k][j]);
                }
            }
        }
    }

    void add(ll from, ll to, ll cost) {
        d[from][to] = cost;
    }

    bool is_negative_loop() {
        for(ll i = 0; i < V; i++) {
            if(d[i][i] < 0) return true;
        }
        return false;
    }

    void show() {
        for(ll i = 0; i < V; i++) {
            for(ll j = 0; j < V; j++) {
                cout << d[i][j] << " ";
            }
            cout << endl;
        }
    }
};

