        cout << "NEGATIVE CYCLE" << endl;
    }
    else {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j) cout << " ";
                if (D[i][j] == inf) cout << "INF";
                else                cout << D[i][j];
            }
            cout << endl;
        }
    }

    return 0;
}

