bool find_negative_loop(long long V, long long E){
	for(int i = 0; i < V; i++) dd[i] = INF;
	dd[0] = 0;
	int flag = 0;

	for(int i = 0; i < V; i++){
		for(int j = 0; j < V; j++) temp[j] = dd[j];

		for(int j = 0; j < E; j++) 
			if(dd[es[j].to] > dd[es[j].from] + es[j].dist)
				dd[es[j].to] = dd[es[j].from] + es[j].dist;

		flag = 0;
		for(int j = 0; j < V; j++)
			if(temp[j] != dd[j]){
				flag = 1;
				break;
			}

		if(flag == 0) break;
	}

	for(int i = 0; i < E; i++)
		if(dd[es[i].to] > dd[es[i].from] + es[i].dist)
			flag = 1;

	return flag;
}

