int G[MAXN][MAXN];

int n, k, u, v, w;


void init()
{
	for(int i = 0; i < n; i++)
		for(int j = 0; j < n; j++)
			G[i][j] = i == j ? 0 : INF;
}

void floyd()
{
	for(int k = 0; k < n; k++)
		for(int i = 0; i < n; i++)
			for(int j = 0; j < n; j++)
			{
				if(min(G[i][j], G[i][k] + G[k][j]) >= NBDR && min(G[i][j], G[i][k] + G[k][j]) <= BDR )
					G[i][j] = min(G[i][j], G[i][k] + G[k][j]);	
				if(G[i][j] > BDR && G[i][j] <=INF )
					G[i][j] = INF;
			}

}


int main()
{
	while(scanf("%d %d", &n, &k) != EOF)
	{
		init();
		int flag = 0;
		while(k--)
		{
			scanf("%d %d %d", &u, &v, &w);
			G[u][v] = w;
		}

		floyd();

		for(int i = 0; i < n; i++)
			if(G[i][i] < 0)
			{
				printf("NEGATIVE CYCLE\n");
				flag = 1;
				break;
			}

		if( flag == 1)
			continue;		

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < n; j++)
			{
				if(G[i][j] == INF && j < n-1)
					printf("INF ");
				else if(G[i][j] == INF && j < n)
					printf("INF");
				else if(G[i][j] != INF && j < n-1)
					printf("%d ", G[i][j]);
				else if(G[i][j] != INF && j < n)
					printf("%d", G[i][j]);
			}
			printf("\n");
		}
	}


	return  0;
}

