  REP(i,v) g[i][i] = 0;
  auto dist = warshal_floyd(g).first;
  if(dist.size()==0){
    cout << "NEGATIVE CYCLE" << endl;
    return 0;
  }
  cout << dist << endl;
  eprint(INF);
}

