//https://qiita.com/wakimiko/items/69b86627bea0e8fe29d5
int Bellman_Ford(ll start, ll vertex , ll edges){
    rep(i,0,vertex) ans[i]=INF;
    ll cnt=0,update=1;
    ans[start] = 0;

    while(update){
        update = 0;
        if(cnt++>vertex) return 0;
        rep(i,0,edges){
            if( ans[edge[i].from]!=INF  &&  ans[ edge[i].to ] > ans[edge[i].from] + edge[i].cost ){
                update=1;
                ans[ edge[i].to ] = ans[edge[i].from] + edge[i].cost;
            }
        }
    }
    return 1;
}

