			if(C[E[i].from]!=INF && C[E[i].to] > C[E[i].from]+E[i].cost){
				C[E[i].to]=C[E[i].from]+E[i].cost;
				cnt++;
			}
		}

	}

	if(cnt>e){
		printf("NEGATIVE CYCLE\n");
