			cost = sc.nextInt();

			min_dist[from][to] = Math.min(min_dist[from][to],cost);
		}

		for(int mid = 0; mid < V; mid++){
			for(int start = 0; start < V; start++){
				if(min_dist[start][mid] == BIG_NUM)continue;
				for(int goal = 0; goal < V; goal++){
					if(min_dist[mid][goal] == BIG_NUM)continue;
					min_dist[start][goal] = Math.min(min_dist[start][goal], min_dist[start][mid]+min_dist[mid][goal]);
				}
			}
		}


		boolean FLG = true;

		for(int i = 0; i < V; i++){
			if(min_dist[i][i] < 0){
				FLG = false;
				break;
			}
		}

		if(!FLG){System.out.println("NEGATIVE CYCLE\n");
			return;
		}

		StringBuilder ans = new StringBuilder();

		for(int i = 0; i < V; i++){
			if(min_dist[i][0] != BIG_NUM){

				ans.append(Integer.toString(min_dist[i][0]));
			}else{
				ans.append("INF");
			}
			for(int k = 1; k < V; k++){
				if(min_dist[i][k] != BIG_NUM){

					ans.append(" ").append(Integer.toString(min_dist[i][k]));
				}else{
					ans.append(" ").append("INF");
				}
			}
			ans.append("\n");
		}
		System.out.print(ans.toString());
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.stream.Stream;

public class Main {

	public static void main(String[] args) throws IOException {
		new Main().solve();
	}

	private void solve() throws IOException {
		try {
			solveA();
		} finally {
			if (in != null) {
				in.close();
			}
			if (out != null) {
				out.flush();
				out.close();
			}
		}

	}

	private void solveA() {
		int v = nextInt();
		int e = nextInt();

		int[][] wk = Stream.generate(() -> new int[] { nextInt(), nextInt(), nextInt() }).limit(e - 1)
				.toArray(int[][]::new);

		int[][] graph = new int[v][v];

		for (int i = 0; i < graph.length; i++) {
			Arrays.fill(graph[i], 1 << 32);
			graph[i][i] = 0;
		}
		for (int i = 0; i < wk.length; i++) {
			int from = wk[i][0];
			int to = wk[i][1];
			graph[from][to] = wk[i][2];
			graph[to][from] = wk[i][2];
		}

		for (int i = 0; i < v; i++) {
			for (int j = 0; j < v; j++) {
				for (int k = 0; k < v; k++) {
					graph[j][k] = Integer.min(graph[j][k], graph[j][i] + graph[i][k]);
				}
			}
		}
		StringBuilder builder = new StringBuilder();
		for (int i = 0; i < graph.length; i++) {
			for (int j = 0; j < graph[i].length; j++) {
				if (graph[i][j] == (1 << 32)) {
					builder.append("INF");
				} else {
					builder.append(graph[i][j]);
				}
				if (graph[i][j] < 0) {
					out.println("NEGATIVE CYCLE");
					return;
				}
				out.println(builder.toString());
				builder.setLength(0);
			}
		}
	}

	private final PrintWriter out = new PrintWriter(System.out);
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	long INF = Long.MAX_VALUE / 10;

	void run() {
		Scanner sc = new Scanner(System.in);
		int V = sc.nextInt();
		int E = sc.nextInt();
		long[][] D = new long[V][V];
		long[][] W = new long[V][V];
		for (int i = 0; i < V; ++i) {
			Arrays.fill(D[i], INF);
			Arrays.fill(W[i], INF);
			W[i][i] = 0;
			D[i][i] = 0;
		}
		for (int i = 0; i < E; ++i)
			D[sc.nextInt()][sc.nextInt()] = sc.nextLong();
		W = mul(pow(D, V), W);
		for (int i = 0; i < V; ++i)
			if (D[i][i] < 0) {
				System.out.println("NEGATIVE CYCLE");
				return;
			}
		for (int i = 0; i < V; ++i)
			for (int j = 0; j < V; ++j)
				System.out.print((W[i][j] >= INF ? "INF" : W[i][j]) + (j == V - 1 ? "\n" : " "));

	}

	long[][] pow(long[][] a, long n) {
		long[][] ret = new long[a.length][a.length];
		for (int i = 0; i < n; ++i) {
			Arrays.fill(ret[i], INF);
			ret[i][i] = 0;
		}
		for (; n > 0; n >>= 1, a = mul(a, a))
			if (n % 2 == 1)
				ret = mul(ret, a);

		return ret;
	}

	long[][] mul(long[][] a, long[][] b) {
		int n = a.length;
		long[][] ret = new long[n][n];
		for (int i = 0; i < n; ++i)
			Arrays.fill(ret[i], INF);

		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				for (int m = 0; m < n; ++m) {
					if (ret[i][j] >= INF && (Math.max(a[i][m], b[m][j]) >= INF))
						ret[i][j] = INF;
					else
						ret[i][j] = Math.min(ret[i][j], a[i][m] + b[m][j]);
				}
			}
		}
		return ret;
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

