	static boolean debug = false;

	static int[][][] directedGraph(int n, int[] from, int[] to, int[] cost) {
		int[] cnt = new int[n];
		for (int i : from) cnt[i]++;

		int[][][] g = new int[n][][];
		for (int i=0; i<n; i++) g[i] = new int[cnt[i]][2];
		for (int i=0; i<from.length; i++) {
			int s = from[i];
			int t = to[i];

			g[s][--cnt[s]][0] = t;
			g[s][cnt[s]][1] = cost[i];
		}

		return g;
	}

	static int[][] floydWarshall(int[][][] g) {
		int n = g.length;
		int[][] d = new int[n][n];
		for (int i=0; i<n; i++) {
			Arrays.fill(d[i], 1<<29);
			d[i][i] = 0;
		}

		for (int cur=0; cur<n; cur++) {
			for (int[] to : g[cur]) {
				int next = to[0];
				d[cur][next] = Math.min(d[cur][next], to[1]);
			}
		}

		for (int k=0; k<n; k++)
			for (int i=0; i<n; i++)
				for (int j=0; j<n; j++)
					d[i][j] = Math.min(d[i][j], d[i][k] + d[k][j]);

		for (int i=0; i<n; i++) {
			if (d[i][i] < 0) {
				return null;
			}
		}

		return d;
	}


	static void solve() {
		int v = in.nextInt();
		int e = in.nextInt();
		int[] s = new int[e];
		int[] t = new int[e];
		int[] d = new int[e];
		for (int i=0; i<e; i++) {
			s[i] = in.nextInt();
			t[i] = in.nextInt();
			d[i] = in.nextInt();
		}
		int[][][] g = directedGraph(v, s, t, d);
		int[][] ans = floydWarshall(g);
		if (ans == null) {
			out.println("NEGATIVE CYCLE");
			return;
		}
		for (int i=0; i<v; i++) {
			for (int j=0; j<v-1; j++) {
				out.print((ans[i][j] >= 1<<28 ? "INF" : ans[i][j])+" ");
			}
			out.println(ans[i][v-1] >= 1<<28 ? "INF" : ans[i][v-1]);
		}
	}

	public static void main(String[] args) {
		debug = args.length > 0;
		long start = System.nanoTime();

		solve();
		out.flush();

		long end = System.nanoTime();
		dump((end - start) / 1000000 + " ms");
		in.close();
		out.close();
	}

	static void dump(Object... o) { if (debug) System.err.println(Arrays.deepToString(o)); }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main {
	int V, E;
	long[][] cost;
	static int INF = Integer.MAX_VALUE;

	public void solve() {
		V = nextInt();
		E = nextInt();

		cost = new long[V][V];
		for (int i = 0; i < V; i++) {
			Arrays.fill(cost[i], INF);
		}

		for (int i = 0; i < V; i++) {
			cost[i][i] = 0;
		}

		for (int i = 0; i < E; i++) {
			int s = nextInt();
			int t = nextInt();
			int d = nextInt();
			cost[s][t] = d;
		}

		for (int i = 0; i < V; i++) {
			for (int j = 0; j < V; j++) {
				for (int k = 0; k < V; k++) {
					cost[j][k] = Math.min(cost[j][k], cost[j][i] + cost[i][k]);
				}
			}
		}

		boolean NEGATIVE = false;

		for (int i = 0; i < V; i++) {
			for (int j = i + 1; j < V; j++) {
				if (cost[i][j] < 0 && cost[j][i] < 0) {
					NEGATIVE = true;
				}
			}
		}

		if (NEGATIVE) {
			out.println("NEGATIVE CYCLE");
		} else {

			for (int i = 0; i < V; i++) {
				for (int j = 0; j < V; j++) {
					if (j != 0)
						out.print(" ");
					if (cost[i][j] == INF) {
						out.print("INF");
					} else {
						out.print(cost[i][j]);
					}
				}
				out.println();
			}
		}
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int MAX = (int) (2e9 + 1);
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    //Floyd-Warshall's Algorithm
    private void solve() throws Exception{
        FastScanner scanner = new FastScanner(System.in);

        int V = scanner.nextInt();
        int E = scanner.nextInt();

        int[][] dist = new int[V][V];
        for(int i = 0; i < V; ++i){
            Arrays.fill(dist[i], MAX);
            dist[i][i] = 0;
        }

        for(int i = 0; i < E; ++i){
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();

            dist[u][v] = w;
        }

        for(int k = 0; k < V; ++k){
            for(int i = 0; i < V; ++i){
                for(int j = 0; j < V; ++j){
                    if(dist[i][k] != MAX && dist[k][j] != MAX && dist[i][j] > dist[i][k] + dist[k][j]){
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }

                if(dist[i][i] < 0){
                    System.out.println("NEGATIVE CYCLE");
                    return;
                }
            }
        }

        PrintWriter printWriter = new PrintWriter(System.out);
        for(int i = 0; i < V; ++i){
            for(int j = 0; j < V; ++j){
                printWriter.print(dist[i][j] == MAX ? "INF" : dist[i][j]);

                if(j != V - 1){
                    printWriter.print(" ");
                }
                else{
                    printWriter.println();
                }
            }
        }

        printWriter.flush();
    }

    static class FastScanner {
        private InputStream in;
        private final byte[] buffer = new byte[1024 * 8];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in){
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

public class Main{

	static int[][] d;
	static int INIT_D = Integer.MAX_VALUE / 2;

	public static void initWF(int n) {
		d = new int[n][n];
		for (int i=0;i<n;i++) {
			for (int j=0;j<n;j++) {
				d[i][j] = INIT_D;
				if (i==j) d[i][j] = 0;
			}
		}
	}

	public static void execWF() {
		int n = d.length;
		for (int k=0;k<n;k++) {
			for (int i=0;i<n;i++) {
				if (d[i][k] == INIT_D) continue;
				for (int j=0;j<n;j++) {
					if (d[k][j] == INIT_D) continue;

					d[i][j] = Math.min(d[i][j], d[i][k]+d[k][j]);
				}
			}
		}
	}

	public static boolean hasNegativeLoop() {
		int n = d.length;
		for (int i=0;i<n;i++) {
			if (d[i][i]<0) return true;
		}
		return false;
	}

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);

		int nv = scan.nextInt();
		int ne = scan.nextInt();

		initWF(nv);

		// read edge data
		for (int i=0;i<ne;i++) {
			int s = scan.nextInt();
			int t = scan.nextInt();
			int dist = scan.nextInt();
			d[s][t] = dist;
			// NOTE:MUST NOT set value in reverse direction
			//d[t][s] = dist;
		}

		execWF();

		// output result
		if (hasNegativeLoop()) {
			System.out.println("NEGATIVE CYCLE");
			return;
		}
		for (int s=0;s<nv;s++) {
			StringBuilder sb = new StringBuilder();
			for (int t=0;t<nv;t++) {
				sb.append(d[s][t]==INIT_D ? "INF" : String.valueOf(d[s][t]));
				sb.append(" ");
			}
			System.out.println(sb.substring(0,sb.length()-1));
		}
	}

}

