		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 29;
	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int v = in.nextInt();
			int e = in.nextInt();
			int[][] w = new int[v][v];
			int len = w.length;
			for (int i = 0; i < len; i++) {
				Arrays.fill(w[i], INF);
			}
			for (int i = 0; i < len; i++) {
				w[i][i] = 0;
			}
			for (int i = 0; i < e; i++) {
				int s = in.nextInt();
				int t = in.nextInt();
				int d = in.nextInt();
				w[s][t] = d;
			}

			warshallFloyd(w);

			StringBuffer sb = new StringBuffer();
			for (int i = 0; i < v; i++) {
				if (w[i][i] < 0) {
					sb = new StringBuffer();
					sb.append("NEGATIVE CYCLE\n");
					break;
				}
				for (int j = 0; j < v; j++) {
					if (j != 0) {
						sb.append(" ");
					}
					if (w[i][j] == INF) {
						sb.append("INF");
					} else {
						sb.append(w[i][j]);
					}
				}
				sb.append("\n");
			}
			out.print(sb.toString());

		}

		void warshallFloyd(int[][] d) {
			int len = d.length;
			for (int i = 0; i < len; i++) {
				for (int j = 0; j < len; j++) {
					if (d[j][i] == INF) continue;
					for (int k = 0; k < len; k++) {
						if (d[i][k] == INF) continue;
						d[j][k] = Math.min(d[j][k], d[j][i] + d[i][k]);
					}
				}
			}
		}
	}

