//	static final int INF = 10_000_001;

	static void solve(int matrix[][]){
		//xからそれぞれのfarmへの帰り道の最短距離
		long[][] dist = warshallFloyd(matrix);

		int n = dist.length;
		for(int i = 0; i < n; i++){
			if(dist[i][i] < 0){
				System.out.println("NEGATIVE CYCLE");
				return;
			}
		}

		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(j != 0){
					System.out.print(" ");
				}
				if(dist[i][j] == INF){
