class WarshallFroyd {

    private int size;
    public long[][] dist;
    public long[][] from;

    public WarshallFroyd(int size) {
        this.size = size;
        dist = new long[size][size];
        for (int i = 0; i < size; i++) {
            Arrays.fill(dist[i], Long.MAX_VALUE / 2);
            dist[i][i] = 0;
        }
        from = new long[size][size];
        for (long[] arr : from) {
            Arrays.fill(arr, -1);
        }
    }

    public void addEdge(int from, int to, int cost) {
        dist[from][to] = cost;
    }

    public void run() {
        for (int via = 0; via < size; via++) {
            for (int fr = 0; fr < size; fr++) {
                for (int to = 0; to < size; to++) {
                    if (dist[fr][via] != Long.MAX_VALUE / 2
                            && dist[via][to] != Long.MAX_VALUE / 2
                            && dist[fr][to] > dist[fr][via] + dist[via][to]) {
                        dist[fr][to] = dist[fr][via] + dist[via][to];
                        from[fr][to] = via;
                    }
                }
            }
        }
    }
}


class Edge {
    public final int from;
    public final int to;
    public final int cost;

    public Edge(int from, int to, int cost) {
        this.from = from;
        this.to = to;
        this.cost = cost;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Edge edge = (Edge) o;
        return from == edge.from &&
                to == edge.to &&
                cost == edge.cost;
    }

    @Override
    public int hashCode() {
        return Objects.hash(from, to, cost);
    }
}

