    public static void display(long[,] dp)
    {
        var n = dp.GetLength(0);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i == j && dp[i, j] < 0)
                { Console.WriteLine("NEGATIVE CYCLE"); return; }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (j == n - 1)
                {
                    if (dp[i, j] == C.INF) Console.WriteLine("INF");
                    else Console.WriteLine(dp[i, j]);
                }
                else if (dp[i, j] == C.INF) Console.Write("INF ");
                else Console.Write("{0} ", dp[i, j]);
    }
    public static void goWarshall(long[,] dp)
    {

        var n = dp.GetLength(0);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                {
                    if (dp[j, i] != C.INF && dp[i, k] != C.INF)
                        dp[j, k] = Math.Min(dp[j, k], dp[j, i] + dp[i, k]);
                }
    }
