using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;
class Solve{
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        string[] str = Console.ReadLine().Split(' ');
        int N = int.Parse(str[0]);
        int E = int.Parse(str[1]);
        long[,] cost = new long[N,N];
        long INF = 1000000000000000;
        for(int i=0;i<N;i++){
            for(int j=0;j<N;j++){
                if(i != j){
                    cost[i,j] = INF;
                }
            }
        }
        for(int i=0;i<E;i++){
            str = Console.ReadLine().Split(' ');
            int f = int.Parse(str[0]);
            int t = int.Parse(str[1]);
            cost[f,t] = Math.Min(int.Parse(str[2]),cost[f,t]);
        }
        for(int i=0;i<N;i++){
            for(int j=0;j<N;j++){
                for(int k=0;k<N;k++){
                    if(cost[i,k] != INF && cost[k,j] != INF){
                        cost[i,j] = Math.Min(cost[i,j],cost[i,k]+cost[k,j]);
                    }
                }
            }
        }
        bool NegativeCycle = false;
        for(int i=0;i<N;i++){
            if(cost[i,i] < 0){
                NegativeCycle = true;
            }
        }
        if(NegativeCycle){
            sb.Append("NEGATIVE CYCLE\n");
        }
        else{
            for(int i=0;i<N;i++){
                for(int j=0;j<N;j++){
                    sb.Append(cost[i,j] == INF ? "INF " : (cost[i,j]+" "));
                }
                sb.Append("\n");
            }
        }
    }
}

