        }
        struct Rinf
        {
            public bool isInf;
            public int value;

            public static Rinf operator +(Rinf x, Rinf y)
            {
                Rinf n = new Rinf();
                if (!x.isInf && !y.isInf)
                {
                    n.isInf = false;
                    n.value = x.value + y.value;
                    return n;
                }
                else 
                {
                    n.isInf = true;
                    n.value = 0;
                    return n;
                }
            }
            public static bool operator <(Rinf x, Rinf y) 
            {
                if (x.isInf)
                    return false;
                else if (y.isInf)
                    return true;
                else
                {
                    if (x.value < y.value)
                        return true;
                    else
                        return false;
                }
            }
            public static bool operator >(Rinf x, Rinf y)
            {
                return y < x;
            }

        }

    }
