public static class ShortestPath
{
	public struct Edge<T>
	{
		public long From;
		public long To;
		public T Cost;

		public Edge(long from, long to, T cost)
		{
			From = from;
			To = to;
			Cost = cost;
		}
	}

	// false: has negative cycle
	public static bool BellmanFord<T>(long N, List<Edge<T>> edges, long s, T inf, Func<T, T, T> add, out T[] d) where T : IComparable<T>
	{
		d = Enumerable.Repeat(inf, (int)N).ToArray();
		d[s] = default(T);
		for(long i = 0; i < N; i++)
		{
			bool update = false;
			foreach(var e in edges)
			{
				var tmp = add(d[e.From], e.Cost);
				if((d[e.From].CompareTo(inf) < 0) && (d[e.To].CompareTo(tmp) > 0))
				{
					d[e.To] = tmp;
					update = true;
					if(i == N - 1)
						return false;
				}
			}
			if(!update)
				break;
		}
		return true;
	}

	public static bool HasNegativeCycle<T>(long N, List<Edge<T>> edges, Func<T, T, T> add) where T : IComparable<T>
	{
		var d = new T[N];		
		for(long i = 0; i < N; i++)
		{
			foreach(var e in edges)
			{
				var tmp = add(d[e.From], e.Cost);
				if(d[e.To].CompareTo(tmp) > 0)
				{
					d[e.To] = tmp;
					if(i == N - 1)
						return true;
				}
			}
		}
		return false;
	}

	public static T[] Dijkstra<T>(T[,] cost, T inf, long s, Func<T, T, T> add) where T : IComparable<T>
	{
		long V = cost.GetLength(0);	
		var used = new bool[V];
		var d = Enumerable.Repeat(inf, (int)V).ToArray();
		d[s] = default(T);

		while(true)
		{
			long v = -1;
			for(long u = 0; u < V; u++)
				if(!used[u] && (v == -1 || d[u].CompareTo(d[v]) < 0))
					v = u;

			if(v == -1)
				break;

			used[v] = true;
			for(long u = 0; u < V; u++)
			{
				var tmp = add(d[v], cost[v, u]);
				if(d[u].CompareTo(tmp) > 0)
					d[u] = tmp;
			}
		}
		return d;
	}

	public static T[] Dijkstra<T>(List<Edge<T>>[] adj, T inf, long s, Func<T, T, T> add) where T : IComparable<T>
	{
		Comparison<Tuple<T, long>> comp = ((x, y) => x.Item1.CompareTo(y.Item1));
		var pq = new PriorityQueue<Tuple<T, long>>(adj.Length, comp);

		var d = Enumerable.Repeat(inf, adj.Length).ToArray();
		d[s] = default(T);
		pq.Push(Tuple.Create(d[s], s));
		while(pq.Count > 0)
		{
			var p = pq.Pop();
			long v = p.Item2;
			if(d[v].CompareTo(p.Item1) < 0)
				continue;

			for(long i = 0; i < adj[v].Count; i++)
			{
				var edge = adj[v][(int)i];
				var tmp = add(d[v], edge.Cost);
				if(d[edge.To].CompareTo(tmp) > 0)
				{
					d[edge.To] = tmp;
					pq.Push(Tuple.Create(d[edge.To], edge.To));
				}
			}
		}
		return d;
	}

	// false: has negative cycle
	public static bool WarshallFloyd<T>(ref T[,] d, Func<T, T, T> add) where T : IComparable<T>
	{
		long V = d.GetLength(0);
		for(long k = 0; k < V; k++)
		{
			for(long i = 0; i < V; i++)
			{
				for(long j = 0; j < V; j++)
				{
					var tmp = add(d[i, k], d[k, j]);
					if(d[i, j].CompareTo(tmp) > 0)
						d[i, j] = tmp;
				}
			}
		}
		for(long i = 0; i < V; i++)
		{
			if(d[i, i].CompareTo(default(T)) < 0)
				return false;
		}
		return true;
	}
}

public class PriorityQueue<T>
{
	public long Count { get; private set; } = 0;
	public long MaxSize { get; private set; } = 0;
	private T[] m_heap;
	private Comparison<T> Comp = null;

	public PriorityQueue(long maxSize, Comparison<T> comp)
	{
		if(maxSize <= 0)
			throw new Exception();
		MaxSize = maxSize;
		m_heap = new T[maxSize];

		Comp = comp;
	}

	public void Push(T x)
	{
		if(Count == MaxSize)
		{
			T[] new_heap = new T[MaxSize << 1];
			Array.Copy(m_heap, new_heap, MaxSize);
			m_heap = new_heap;
			MaxSize <<= 1;
		}

		long i = Count++;
		while(i > 0)
		{
			long p = (i - 1)/2;
			if(Comp(m_heap[p], x) <= 0)
				break;
			m_heap[i] = m_heap[p];
			i = p;			
		}
		m_heap[i] = x;		
	}

	public T Pop()
	{
		if(Count == 0)
			throw new Exception("Queue is empty.");

		T result = m_heap[0];
		T x = m_heap[--Count];
		long i = 0;
		while(i * 2 + 1 < Count)
		{
			long c1 = i * 2 + 1, c2 = i * 2 + 2;
			if(c2 < Count && Comp(m_heap[c2], m_heap[c1]) < 0)
				c1 = c2;
			if(Comp(m_heap[c1], x) >= 0)
				break;
			m_heap[i] = m_heap[c1];
			i = c1;
		}
		m_heap[i] = x;

		return result;		
	}

	public T Peek() => m_heap[0];
}

