            // ワーシャルフロイド
            for(int k=0;k<v;++k)
            {
                for(int i=0;i<v;++i)
                {
                    for(int j=0;j<v;++j)
                    {
                        int cost = 0;
                        if( dp[i,k] == int.MaxValue || dp[k, j] == int.MaxValue)
                        {
                            cost = int.MaxValue;
                        }else
                        {
                            cost = dp[i, k] + dp[k, j];
                        }
                        dp[i, j] = Math.Min(dp[i, j], cost);
                    }
                }
            }

            // 負の閉路判定
            if(IsNegativeCycle(dp))
            {
                Console.WriteLine("NEGATIVE CYCLE");
                return;
            }
            for(int i=0;i<v;++i)
            {
                string sz = "";
                for(int j=0;j<v;++j)
                {
                    if(dp[i, j] != int.MaxValue)
                    {
                        sz += dp[i, j];
                    }else
                    {
                        sz += "INF";
                    }
                    if( j < v - 1)
                    {
                        sz += " ";
                    }
                }
                Console.WriteLine(sz);
            }
        }
        private static bool IsNegativeCycle(int[, ] dp)
        {
            for(int i=0;i<dp.GetLength(0);++i)
            {
                if(dp[i,i] < 0)
                {
                    return true;
                }
            }
            return false;
        }
    }
}

