            int E = int.Parse(input[1]);

            int[,] dp = new int[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++)
                {
                    dp[i, j] = i == j ? 0 : INFTY;
                }
            }

            int s, t, d;
            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                s = int.Parse(input[0]);
                t = int.Parse(input[1]);
                d = int.Parse(input[2]);

                dp[s, t] = d;
            }

            WarshallFloyd(dp, V);

            bool isNegative = false;
            for (int i = 0; i < V; i++)
            {
                if (dp[i, i] < 0)
                {
                    isNegative = true;
                    break;
                }
            }

            StringBuilder sb = new StringBuilder();
            if (isNegative) sb.AppendLine("NEGATIVE CYCLE");
            else
            {
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        if (j != 0) sb.Append(" ");
