using Enu = System.Linq.Enumerable;

public class Program
{
    static readonly int INF = int.MaxValue;

    public void Solve()
    {
        int V = Reader.Int(), E = Reader.Int();
        var dist = new int[V, V];

        for (int a = 0; a < V; a++)
            for (int b = 0; b < V; b++)
                dist[a, b] = a == b ? 0 : INF;
        for (int i = 0; i < E; i++)
        {
            int a = Reader.Int(), b = Reader.Int(), c = Reader.Int();
            CheckMin(ref dist[a, b], c);
        }
        for (int c = 0; c < V; c++)
            for (int a = 0; a < V; a++)
                for (int b = 0; b < V; b++)
                    if (dist[a, c] < INF && dist[c, b] < INF)
                        CheckMin(ref dist[a, b], dist[a, c] + dist[c, b]);
        if (Enu.Range(0, V).Any(a => dist[a, a] < 0))
        {
            Console.WriteLine("NEGATIVE CYCLE");
            return;
        }
        for (int a = 0; a < V; a++)
        {
            for (int b = 0; b < V; b++)
            {
                Console.Write(dist[a, b] == INF ? "INF" : dist[a, b] + "");
                if (b < V - 1) Console.Write(" ");
            }
            Console.WriteLine();
        }
        Console.ReadLine();
    }

    bool CheckMin(ref int a, int b) { if (b < a) { a = b; return true; } return false; }

}


