namespace ConsoleApplication1
{
    class Program
    {
        /// <summary>
        /// find the shortest path from start to all destination
        /// </summary>
        public class BellmanFord
        {
            public List<edge> Edge = new List<edge>();
            public int V;   // number of vertex

            public class edge
            {
                public int from, to, cost;
                public edge(int _from, int _to, int _cost)
                {
                    from = _from;
                    to = _to;
                    cost = _cost;
                }
            }

            public BellmanFord(int v)
            {
                V = v;
            }

            /// <summary>
            ///  return shortestPath[V] represents distance from startIndex
            ///  null if there are negative loop from the startIndex
            /// </summary>
            public int[] GetShortestPath(int startIndex)
            {
                int[] shortestPath = new int[V];
                var INF = Int32.MaxValue;

                for (int i = 0; i < V; i++) shortestPath[i] = INF;
                shortestPath[startIndex] = 0;

                var cnt = 0;
                while (true)
                {
                    bool update = false;
                    foreach (edge e in Edge)
                    {
                        if (shortestPath[e.from] != INF && shortestPath[e.to] > shortestPath[e.from] + e.cost)
                        {
                            shortestPath[e.to] = shortestPath[e.from] + e.cost;
                            update = true;
                        }
                    }
                    if (!update) break;

                    cnt++;
                    if (cnt == V - 1) return null;
                }

                return shortestPath;
            }

            /// <summary>
            ///  return true if it has any negative close loop
            /// </summary>
            public bool HasAnyNegativeLoop()
            {
                int[] d = new int[V];
                for (int i = 0; i < V; i++)
                {
                    foreach (edge e in Edge)
                    {
                        if (d[e.to] > d[e.from] + e.cost)
                        {
                            d[e.to] = d[e.from] + e.cost;
                            if (i == V - 1) return true;
                        }
                    }
                }
                return false;
            }
        }

        public class WarshallFloyd
        {
            int[,] dist;
            public int V;

            public WarshallFloyd(int v)
            {
                V = v;
                dist = new int[v, v];

                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        dist[i, j] = Int32.MaxValue;
                        if (i == j) dist[i, j] = 0;
                    }
                }
            }

            public void AddEdge(int s, int t, int c)
            {
                dist[s, t] = c;
            }

            public int[,] GetDistances()
            {
                for (int k = 0; k < V; k++)
                {
                    for (int i = 0; i < V; i++)
                    {
                        for (int j = 0; j < V; j++)
                        {
                            dist[i, j] = Math.Min(dist[i, j], dist[i, k] == Int32.MaxValue || dist[k, j] == Int32.MaxValue ? Int32.MaxValue : dist[i, k] + dist[k, j]);
                        }
                    }
                }
                return dist;
            }
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var V = Int32.Parse(str[0]);
            var E = Int32.Parse(str[1]);

            var bellmanFord = new BellmanFord(V);
            var warshallFloyd = new WarshallFloyd(V);

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine().Split();
                var s = Int32.Parse(str[0]);
                var t = Int32.Parse(str[1]);
                var d = Int32.Parse(str[2]);
                bellmanFord.Edge.Add(new BellmanFord.edge(s, t, d));
                warshallFloyd.AddEdge(s, t, d);
            }

            if (bellmanFord.HasAnyNegativeLoop())
            {
                Console.WriteLine("NEGATIVE CYCLE");
            }
            else
            {
                var dist = warshallFloyd.GetDistances();
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        Console.Write(string.Format("{0} ", dist[i, j] == Int32.MaxValue ? "INF" : dist[i, j]));
                    }
                    Console.WriteLine();
                }
            }
        }
    }
}

