            for (var i = 0; i < n; ++i)
                for (var j = 0; j < n; ++j)
                { d[i, j] = i == j ? 0 : long.MaxValue; }
            for (var i = 0; i < n; ++i)
                foreach (var kv in M[i])
                    d[i, kv.Key] = kv.Value;

            for (var k = 0; k < n; ++k)
