                for (var i = 0; i < n; ++i)
                {
                    if (d[i, k] == long.MaxValue) continue;
                    for (var j = 0; j < n; ++j)
                    {
                        if (d[k, j] == long.MaxValue) continue;
                        d[i, j] = Math.Min(d[i, j], d[i, k] + d[k, j]);
                    }
                }
            }
            return d;
        }
