            {
                for (int i = 0; i < v; ++i)
                {
                    string s = "";
                    for (int j = 0; j < v; ++j)
                    {
                        if (!ans[i, j].isInf)
                            s += ans[i, j].value.ToString();
                        else
                            s += "INF";

                        if (j < v - 1)
                            s += " ";
                    }
                    Console.WriteLine(s);
                }
            }

        }
        struct Rinf
        {
            public bool isInf;
            public int value;

            public static Rinf operator +(Rinf x, Rinf y)
            {
                Rinf n = new Rinf();
                if (!x.isInf && !y.isInf)
                {
                    n.isInf = false;
                    n.value = x.value + y.value;
                    return n;
                }
                else 
                {
                    n.isInf = true;
                    n.value = 0;
                    return n;
                }
            }
            public static bool operator <(Rinf x, Rinf y) 
            {
                if (x.isInf)
                    return false;
                else if (y.isInf)
                    return true;
                else
                {
                    if (x.value < y.value)
                        return true;
                    else
                        return false;
                }
            }
            public static bool operator >(Rinf x, Rinf y)
            {
                return y < x;
            }

        }

    }
}

