    public class WarshallFloyd{
        public const long INF = long.MaxValue / 2;
        private readonly int _v;
        private readonly long[][] _dist;

        public WarshallFloyd(int v){
            _v = v;
            _dist = new long[v][];
            for(var i = 0; i < v; i++){
                _dist[i] = new long[v];
            }

            for(var i = 0; i < v; i++){
                for(var j = 0; j < v; j++){
                    if(i != j) _dist[i][j] = INF;
                }
            }
        }

        public void AddEdge(int from, int to, int cost){
            _dist[from][to] = cost;
        }

        public long[][] Solve(){
            for(var k = 0; k < _v; k++){
                for(var i = 0; i < _v; i++){
                    for(var j = 0; j < _v; j++){
                        _dist[i][j] = Math.Min(_dist[i][j], _dist[i][k] + _dist[k][j]);
                    }
                }
            }

            for(var i = 0; i < _v; i++){
                if(_dist[i][i] < 0) return null;
            }

            return _dist;
        }
    }

    public class BellmanFord{
        public class Edge{
            public int From;
            public int To;
            public int Cost;
        }

        private readonly int _v;
        private readonly List<Edge> _es;

        public BellmanFord(int v){
            _v = v;
            _es = new List<Edge>();
        }

        public void AddEdge(int from, int to, int cost){
            _es.Add(new Edge{From = from, To = to, Cost = cost});
        }

        public int[] Solve(int start){
            var dist = new int[_v];

            for(var i = 0; i < _v; i++) dist[i] = int.MaxValue;
            dist[start] = 0;

            for(var i = 0; i < _v; i++){
                var end = true;
                foreach(var e in _es){
                    if(dist[e.From] != int.MaxValue && dist[e.To] > dist[e.From] + e.Cost){
                        dist[e.To] = dist[e.From] + e.Cost;
                        end = false;
                    }
                }
                if(end) return dist;
            }

            return null;
        }
    }

