        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int V = int.Parse(input[0]);
            int E = int.Parse(input[1]);

            int[,] dp = new int[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++)
                {
                    dp[i, j] = i == j ? 0 : INFTY;
                }
            }

            int s, t, d;
            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                s = int.Parse(input[0]);
                t = int.Parse(input[1]);
                d = int.Parse(input[2]);

                dp[s, t] = d;
            }

            WarshallFloyd(dp, V);

            StringBuilder sb = new StringBuilder();
            if (IsNegative(dp, V))
            {
                sb.AppendLine("NEGATIVE CYCLE");
            }
            else
            {
                for (int i = 0; i < V; i++)
                {
                    for (int j = 0; j < V; j++)
                    {
                        if (j != 0) sb.Append(" ");
                        sb.Append(dp[i, j] == INFTY ? "INF" : dp[i, j].ToString());
                    }
                    sb.AppendLine();
                }
            }
            Console.Write(sb);
        }

        static void WarshallFloyd(int[,] dp, int V)
        {
            for (int k = 0; k < V; k++)
            {
                for (int i = 0; i < V; i++)
                {
                    if (dp[i, k] == INFTY) continue;
                    for (int j = 0; j < V; j++)
                    {
                        if (dp[k, j] == INFTY) continue;
                        dp[i, j] = Math.Min(dp[i, j], dp[i, k] + dp[k, j]);
                    }
                }
            }
        }

        static bool IsNegative(int[,] dp, int V)
        {
            for (int i = 0; i < V; i++)
            {
                if (dp[i, i] < 0) return true;
            }
            return false;
        }
    }
