func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	v := getNextInt(scanner)
	e := getNextInt(scanner)
	fw := makeGrid(v, v)
	for i := 0; i < v; i++ {
		for j := 0; j < v; j++ {
			if i == j {
				continue
			}
			fw[i][j] = math.MaxInt32
		}
	}
	for i := 0; i < e; i++ {
		s := getNextInt(scanner)
		t := getNextInt(scanner)
		d := getNextInt(scanner)
		fw[s][t] = d
	}
	for k := 0; k < v; k++ {
		for i := 0; i < v; i++ {
			for j := 0; j < v; j++ {
				if fw[i][k] == math.MaxInt32 {
					continue
				}
				if fw[k][j] == math.MaxInt32 {
					continue
				}
				if fw[i][j]-fw[i][k] > fw[k][j] {
					fw[i][j] = fw[i][k] + fw[k][j]
				}
			}
		}
	}
	for k := 0; k < v; k++ {
		for i := 0; i < v; i++ {
			for j := 0; j < v; j++ {
				if fw[i][k] == math.MaxInt32 {
					continue
				}
				if fw[k][j] == math.MaxInt32 {
					continue
				}
				if fw[i][j]-fw[i][k] > fw[k][j] {
					fmt.Fprintln(writer, "NEGATIVE CYCLE")
					return
				}
			}
		}
	}
	for i := 0; i < v; i++ {
		for j := 0; j < v; j++ {
			if j > 0 {
				fmt.Fprint(writer, " ")
			}
			if fw[i][j] == math.MaxInt32 {
				fmt.Fprint(writer, "INF")
				continue
			}
			fmt.Fprint(writer, fw[i][j])
		}
		fmt.Fprintln(writer, "")
	}
}
func makeGrid(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

