const inf = 100000000000000000
const infMin = 100000000000000

func warshallFloyd(v, e int, edges []edge) {
	dp := make([][]int, v)
	for i := 0; i < v; i++ {
		dp[i] = make([]int, v)
		for j := 0; j < v; j++ {
			if i != j {
				dp[i][j] = inf
			}
		}
	}
	for _, e := range edges {
		dp[e.from][e.to] = e.cost
	}
	for k := 0; k < v; k++ {
		for i := 0; i < v; i++ {
			for j := 0; j < v; j++ {
				dp[i][j] = min(dp[i][j], dp[i][k]+dp[k][j])
			}
		}
	}
	for i := 0; i < v; i++ {
		if dp[i][i] < 0 {
			fmt.Println("NEGATIVE CYCLE")
			return
		}
	}
	for i := 0; i < v; i++ {
		for j := 0; j < v; j++ {
			if dp[i][j] > infMin {
				fmt.Print("INF")
			} else {
				fmt.Print(dp[i][j])
			}
			if j == v-1 {
				fmt.Print("\n")
			} else {
				fmt.Print(" ")
			}
		}
	}
}

