// dpをグローバルに設定する必要がある
func warshallFloyd(n int) {
	// dp[u][v] = e[u][v] or INF
	// dp[i][i] = 0
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				// 1. 頂点kをちょうど一度通る場合
				// 2. 頂点kを全く通らない場合
				// の排反な2ケースを加味したもの
				dp[i][j] = Min(dp[i][j], dp[i][k]+dp[k][j])
			}
		}
	}
}

