enum infl = 1_001_001_001_001_001_001L;


void main() {
    int N, M;
    scan(N, M);

    auto dist = new long[][](N, N);
    fillAll(dist, infl);
    foreach (i ; 0 .. N) {
        dist[i][i] = 0;
    }

    foreach (i ; 0 .. M) {
        int ui, vi, ci;
        scan(ui, vi, ci);
        dist[ui][vi] = ci;
    }

    foreach (k ; 0 .. N) {
        foreach (i ; 0 .. N) {
            foreach (j ; 0 .. N) {
                if (dist[i][k] == infl || dist[k][j] == infl) continue;
                chmin(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }

    bool nc = false;

    foreach (i ; 0 .. N) {
        if (dist[i][i] < 0) nc = true;
    }

    if (nc) {
        writeln("NEGATIVE CYCLE");
        return;
    }

    foreach (i ; 0 .. N) {
        foreach (j ; 0 .. N) {
            write(dist[i][j] < infl ? dist[i][j].to!string : "INF");
            write(j == N - 1 ? '\n' : ' ');
        }
    }
}

