def BellmanFord(s, v, edge):
    dp = [INF] * v
    dp[s] = 0
    for i in range(0, v):
        for fr, to, d in edge:
            if dp[fr] == INF:
                continue
            if dp[to] > dp[fr] + d:
                dp[to] = dp[fr] + d
                if i == v - 1:
                    return -1
    return dp

