import collections


class WarshallFloyd():
    def __init__(self, N):
        self.edges = []
        self.N = N
        self.d = [[float("inf") for i in range(N)]
                  for i in range(N)]  # d[u][v] : 辺uvのコスト(存在しないときは'inf')

    def add(self, u, v, c, directed=False):
        """
        0-indexedであることに注意
        u = from, v = to, c = cost
        directed = Trueなら、有向グラフである
        """
        if directed:
            self.d[u][v] = c
        else:
            self.d[u][v] = c
            self.d[v][u] = c
        if directed:
            self.edges.append([u, v, c])
        else:
            self.edges.append([u, v, c])
            self.edges.append([v, u, c])


    def WarshallFloyd_search(self):
        # これを d[i][j]: iからjへの最短距離 にする
        # 本来無向グラフでのみ全域木を考えるが、二重辺なら有向でも行ける
        for k in range(self.N):
            for i in range(self.N):
                for j in range(self.N):
                    self.d[i][j] = min(
                        self.d[i][j], self.d[i][k] + self.d[k][j])
        for i in range(self.N):
            self.d[i][i] = 0
        return self.d

    def BellmanFord_negative_bool(self, numNodes, start, zero_indexed=False):
        # 負の閉路の検出, Trueなら負の閉路が存在する
        dd = collections.defaultdict(lambda: float('inf'))
        dd[0] = 0
        numEdges = len(self.edges)
        for i in range(numNodes):
            for j in range(numEdges):
                e = self.edges[j]
                if dd[e[1]] > dd[e[0]] + e[2]:
                    dd[e[1]] = dd[e[0]] + e[2]
                    if i == numNodes-1:
                        return True
        return False


