	COMPILE=123456789012
	def compile(a,b,c):
		return ((a+COMPILE)<<18) | (b<<9) | c
	def decompile(a):
		return ((a>>18)-COMPILE,(a>>9)&511,a&511)
else:
	def compile(a,b,c):
		return (a,b,c)
	def decompile(a):
		return a
