// O(V^3)
fn all_shortest_path(adjm: &mut Vec<Vec<i64>>) -> bool {
    let n = adjm.len();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if adjm[i][j] > adjm[i][k] + adjm[k][j] && adjm[i][k] != INF && adjm[k][j] != INF {
                    adjm[i][j] = adjm[i][k] + adjm[k][j];
                }
            }
        }
    }
    for i in 0..n {
        if adjm[i][i] < 0 {
            return false;
        }
    }
    true
}

fn solve() {
    let (v, e): (usize, usize) = (read::<usize>(), read::<usize>());
    let mut adjm = vec![vec![INF; v]; v];
    for _ in 0..e {
        let (s, t, cost): (usize, usize, i64) = (read::<usize>(), read::<usize>(), read::<i64>());
        adjm[s][t] = cost;
    }
    for i in 0..v {
        adjm[i][i] = 0;
    }
    if all_shortest_path(&mut adjm) {
        for i in 0..v {
            for j in 0..v {
                if adjm[i][j] == INF {
                    print!("INF");
                } else {
                    print!("{}", adjm[i][j]);
                }
                if j != v - 1 {
                    print!(" ");
                }
            }
            println!("");
        }
    } else {
        println!("NEGATIVE CYCLE");
    }
}

