mod utils {
    use std::error::Error;
    use std::io::stdin;
    use std::str::FromStr;

    #[allow(dead_code)]
    pub fn read_line<T>() -> Result<Vec<T>, Box<Error>>
    where
        T: FromStr,
        T::Err: 'static + Error,
    {
        let mut line = String::new();
        let _ = stdin().read_line(&mut line)?;
        let parsed_line = line.split_whitespace()
            .map(|x| x.parse::<T>())
            .collect::<Result<Vec<T>, T::Err>>()?;

        Ok(parsed_line)
    }

    #[allow(dead_code)]
    pub fn read_lines<T>(n: usize) -> Result<Vec<Vec<T>>, Box<Error>>
    where
        T: FromStr,
        T::Err: 'static + Error,
    {
        (0..n).map(|_| read_line()).collect()
    }
}

fn solve() -> Result<(), Box<std::error::Error>> {
    let header = utils::read_line::<usize>()?;
    let n_nodes = header[0];
    let n_edges = header[1];
    let edges = utils::read_lines::<i32>(n_edges)?;
    let mut distances = vec![vec![None as Option<i32>; n_nodes]; n_nodes];

    for i in 0..n_nodes {
        distances[i][i] = Some(0);
    }

    // initial distance
    for edge in edges {
        distances[edge[0] as usize][edge[1] as usize] = Some(edge[2]);
    }

    // update distances
    for k in 0..n_nodes {
        for i in 0..n_nodes {
            for j in 0..n_nodes {
                let d_ikj = if distances[i][k].is_some() && distances[k][j].is_some() {
                    Some(distances[i][k].unwrap() + distances[k][j].unwrap())
                } else {
                    None
                };
                let d_ij = distances[i][j];

                distances[i][j] = if d_ij.is_some() {
                    if d_ikj.is_some() {
                        Some(std::cmp::min(d_ij.unwrap(), d_ikj.unwrap()))
                    } else {
                        d_ij
                    }
                } else {
                    if d_ikj.is_some() {
                        d_ikj
                    } else {
                        None
                    }
                };
            }
        }
    }

    for row in distances {
        let row_string: String = row.iter()
            .map(|d_opt| match *d_opt {
                Some(d) => d.to_string(),
                None => "INF".to_string(),
            })
            .collect::<Vec<String>>()
            .join(" ");
        println!("{}", row_string);
    }
    Ok(())
}

fn main() {
    match solve() {
        Err(err) => panic!("{}", err),
        _ => (),
    };
}

