    fn left_size(&self) -> usize;
    fn right_size(&self) -> usize;
    fn left_vs(&self) -> std::slice::Iter<Vite>;
    fn right_vs(&self) -> std::slice::Iter<Vite>;
}

pub struct DirectedGraph<V: Vertex, E: Edge> {
    n: usize,
    m: usize,
    g: Vec<Vec<Eite>>,
    es: Vec<E>,
    vs: Vec<V>
}

impl<'a,V: Vertex, E: Edge> Graph<'a,V,E> for DirectedGraph<V,E> {
    type EsIter = std::slice::Iter<'a,Eite>;
    fn add_edge(&mut self, e: E) {
        let ei = Eite(self.m);
        self.m += 1;
        self.g[e.from().0].push(ei);
        self.es.push(e);
    }
    fn delta(&'a self, v: &Vite) -> Self::EsIter {
        self.g[v.0].iter()
    }
    fn edge(&self, e: &Eite) -> &E {
        &self.es[e.0]
    }
    fn vertex(&self, v: &Vite) -> &V {
       &self.vs[v.0]
    }
    fn v_size(&self) -> usize {
        self.n
    }
    fn e_size(&self) -> usize {
        self.m
    }
}

impl<'a,V: Vertex, E: Edge> Directed<'a,V,E> for DirectedGraph<V,E> {  }

impl<V: Vertex, E: Edge> DirectedGraph<V,E> {
    pub fn new(n: usize) -> Self {
        let mut g = DirectedGraph {
            n: n,
            m: 0,
            g: vec![Vec::<Eite>::new(); n],
            es: Vec::<E>::new(),
            vs: Vec::<V>::new()
        };
        for i in 0..n {
            g.vs.push(V::new(i));
        }
        g
    }
}



use std::cmp::min;

pub fn warshall_floyd_apsp<'a,V,E,G,W,F>(g: &'a G,fp: F) -> Vec<Vec<Option<W>>>
where V: Vertex , E: Edge,G: Graph<'a,V,E>, W: Weighted , F: Fn(&E) -> W {
    let n = g.v_size();
    let mut dist = vec![vec![None; n];n];

    for v in 0..n {
        dist[v][v] = Some(W::zero());
        for e in g.delta(&Vite(v)) {
            let u = to(Vite(v), g.edge(e)).0;
            dist[v][u] = Some(fp(g.edge(e)));
        }
    }

    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                dist[i][j] = match (dist[i][j], dist[i][k], dist[k][j]){
                    (None, Some(d1), Some(d2)) => Some(d1 + d2),
                    (Some(d), Some(d1), Some(d2)) => Some(min(d1 + d2, d)),
                    (d, _, _) => d
                }
            }
        }
    }

    dist
}
